import React, { useEffect } from "react";
import "../../styles/CaseStoryDetails.css";
import CustomerReviews from "../CustomerReviews";
import Cta from "../Cta";
import { FaShopify } from "react-icons/fa6";
import { MdLocationPin } from "react-icons/md";
import { ShoppingBag } from "lucide-react";

const ThirdCaseStory = () => {
  useEffect(() => {
    // ===== Blur Vanish Effect =====
    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          if (entry.target.id === "missionProgress") {
            setTimeout(() => {
              entry.target.classList.add("animate");
            }, 500);
          }
        }
      });
    }, observerOptions);

    const blurElements = document.querySelectorAll(
      ".blur-vanish, .blur-vanish-left, .blur-vanish-right, .blur-vanish-scale, .stagger-item, .blur-glow, .floating-blur, .text-blur-reveal",
    );
    blurElements.forEach((el) => observer.observe(el));

    const progressBar = document.getElementById("missionProgress");
    if (progressBar) observer.observe(progressBar);

    // ===== Hover Effects =====
    const hoverElements = document.querySelectorAll(".enhanced-hover");
    hoverElements.forEach((el) => {
      el.addEventListener("mouseenter", function () {
        this.style.transform = "translateY(-8px) scale(1.02)";
        this.style.boxShadow = "0 20px 40px rgba(92, 39, 254, 0.15)";
        this.style.filter = "drop-shadow(0 8px 16px rgba(0, 0, 0, 0.1))";
      });
      el.addEventListener("mouseleave", function () {
        this.style.transform = "";
        this.style.boxShadow = "";
        this.style.filter = "";
      });
    });

    // ===== Dynamic Cursor =====
    const interactiveElements = document.querySelectorAll(
      ".btn-primary, .cta-button, .enhanced-hover",
    );
    interactiveElements.forEach((el) => {
      el.addEventListener("mouseenter", () => {
        document.body.style.cursor = "pointer";
      });
      el.addEventListener("mouseleave", () => {
        document.body.style.cursor = "default";
      });
    });

    // ===== Ripple Effect =====
    const buttons = document.querySelectorAll(".btn-primary, .cta-button");
    buttons.forEach((btn) => {
      btn.addEventListener("click", function (e) {
        const ripple = document.createElement("span");
        const rect = this.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height);
        const x = e.clientX - rect.left - size / 2;
        const y = e.clientY - rect.top - size / 2;

        ripple.style.cssText = `
          position: absolute;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.6);
          transform: scale(0);
          animation: ripple 0.6s linear;
          width: ${size}px;
          height: ${size}px;
          left: ${x}px;
          top: ${y}px;
          pointer-events: none;
        `;

        this.style.position = "relative";
        this.style.overflow = "hidden";
        this.appendChild(ripple);
        setTimeout(() => ripple.remove(), 600);
      });
    });

    const style = document.createElement("style");
    style.textContent = `
      @keyframes ripple {
        to { transform: scale(4); opacity: 0; }
      }
    `;
    document.head.appendChild(style);

    // ===== Scroll Effects =====
    const onScroll = () => {
      const scrolled = window.pageYOffset;
      const header = document.getElementById("header");
      if (scrolled > 100) {
        header?.classList.add("scrolled");
      } else {
        header?.classList.remove("scrolled");
      }
      const heroImage = document.querySelector(".hero-image");
      if (heroImage) {
        heroImage.style.transform = `translateY(${scrolled * 0.3}px)`;
      }
    };
    window.addEventListener("scroll", onScroll);

    // ===== Smooth Anchor Scroll =====
    const anchors = document.querySelectorAll('a[href^="#"]');
    anchors.forEach((a) => {
      a.addEventListener("click", function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute("href"));
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    // ===== Floating Avatars =====
    const avatars = document.querySelectorAll(".team-avatar");
    avatars.forEach((avatar, i) => {
      avatar.style.animation = "float 3s ease-in-out infinite";
      avatar.style.animationDelay = `${i * 0.5}s`;
    });

    const floatingStyle = document.createElement("style");
    floatingStyle.textContent = `
      @keyframes float {
        0%, 100% { transform: translateY(0px); }
        50% { transform: translateY(-10px); }
      }
    `;
    document.head.appendChild(floatingStyle);

    // ===== Mousemove 3D Cards =====
    const cards = document.querySelectorAll(
      ".client-card, .team-card, .vision-item, .why-card",
    );
    document.addEventListener("mousemove", (e) => {
      cards.forEach((card) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
          const centerX = rect.width / 2;
          const centerY = rect.height / 2;
          const rotateX = (y - centerY) / 10;
          const rotateY = (centerX - x) / 10;
          card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.02)`;
        } else {
          card.style.transform = "";
        }
      });
    });

    // ===== Cleanup =====
    return () => {
      window.removeEventListener("scroll", onScroll);
      observer.disconnect();
    };
  }, []);

  return (
    <>
      <div className="case-story-container">
        {/* ── Hero Banner ── */}
        <section className="case-details-hero-banner">
          <div className="case-details-hero-pattern"></div>
          <div className="case-details-container">
            <div className="case-details-hero-content">
              <div className="case-study-badge">
                <i className="fas fa-star"></i>
                SUCCESS STORY
              </div>
              <h1 className="melissa-hero-title">
                Their store looked fine, but it was quietly killing sales.
              </h1>
              <p>
                A scaling DTC brand had traffic, products, and ambition—but
                their outdated Shopify store was holding them back. An 18-day
                redesign doubled conversions and unlocked revenue no ad campaign
                had achieved.
              </p>
              <div className="case-details-hero-stats">
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">2x</span>
                  <span className="case-details-stat-label">
                    CONVERSION RATE
                  </span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">193%</span>
                  <span className="case-details-stat-label">REVENUE LIFT</span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">41%</span>
                  <span className="case-details-stat-label">
                    HIGHER AVG ORDER VALUE
                  </span>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* ── Client Overview Card ── */}
        <div className="case-details-container">
          <div className="case-details-client-card">
            <div className="case-details-client-header">
              <div className="case-details-client-logo">
                <div className="case-details-client-logo">
                  <img
                    src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/ArcVault_76fa639b-78dc-4de6-85ac-62d2b03905db.webp?v=1771989909"
                    alt="ArcVault Logo"
                  />
                </div>
              </div>
              <div className="case-details-client-info">
                <h2>ArcVault</h2>
                <div className="case-details-client-meta">
                  <div className="case-details-meta-item">
                    <ShoppingBag size={16} />
                    Premium Lifestyle &amp; Accessories Brand
                  </div>
                  <div className="case-details-meta-item">
                    <FaShopify />
                    Shopify Platform
                  </div>
                  <div className="case-details-meta-item">
                    <MdLocationPin />
                    United States
                  </div>
                </div>
              </div>
            </div>
            <div className="quick-facts">
              <div className="fact-box">
                <div className="label">Project Duration</div>
                <div className="value">18 Days</div>
              </div>
              <div className="fact-box">
                <div className="label">Primary Issue</div>
                <div className="value">Outdated Store Killing Growth</div>
              </div>
              <div className="fact-box">
                <div className="label">Industry</div>
                <div className="value">Lifestyle &amp; DTC Accessories</div>
              </div>
              <div className="fact-box">
                <div className="label">SERVICES PROVIDED</div>
                <div className="value">Full Shopify Store Redesign</div>
              </div>
            </div>
          </div>
        </div>

        {/* ── Content Wrapper ── */}
        <div className="case-details-content-wrapper">
          {/* ── Challenge Section ── */}
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-exclamation-triangle"></i>
              </div>
              <h2>The Breaking Point</h2>
            </div>
            <p className="section-intro">
              ArcVault had built real momentum. Their paid ads were performing,
              their product line had earned a loyal following, and their monthly
              traffic was growing consistently. On paper, everything pointed to
              a brand on the verge of a breakout. But the numbers told a
              different story. Their conversion rate sat stubbornly at 2%, and
              while that might sound acceptable, it meant 98 out of every 100
              visitors were leaving without buying anything. At an average order
              value of $86, that silent exit was costing them over $3,400 in
              lost revenue every single day.
            </p>
            <p className="section-intro">
              The problem wasn't the product and it wasn't the marketing. It was
              the store itself. Their Shopify theme was two years old, built for
              a smaller brand at an earlier stage, and it showed. The homepage
              felt generic and unconvincing. The product pages lacked the depth
              and credibility a premium brand requires. Navigation was confusing
              on mobile. The checkout felt clunky and dated. And there was no
              visual system tying the brand together, no consistent identity
              that said "this brand is worth trusting with your money." Visitors
              sensed all of it, even if they couldn't name it. And they left.
            </p>

            <div className="challenge-grid">
              <div className="challenge-visual">
                <div className="speed-indicator">
                  <div className="speed-circle">
                    <div className="speed-inner">
                      <span className="speed-score">2%</span>
                      <span className="speed-label">CVR</span>
                    </div>
                  </div>
                </div>
                <div className="problem-tag">
                  <i className="fas fa-times-circle"></i> Revenue Ceiling
                </div>
              </div>

              <div className="challenge-list">
                <div className="challenge-item">
                  <i className="fas fa-paint-brush"></i>
                  <div className="text">
                    <strong>Outdated Theme With No Brand Identity</strong>
                    <p>
                      A two-year-old generic theme that looked like thousands of
                      other Shopify stores, no visual personality, no premium
                      feel, no reason for a visitor to trust the brand over a
                      competitor
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-file-alt"></i>
                  <div className="text">
                    <strong>Weak Product Pages That Couldn't Close</strong>
                    <p>
                      Product pages with thin descriptions, no lifestyle
                      context, no structured benefits section, and a single
                      above-the-fold image, not enough information for a
                      first-time buyer to feel confident purchasing
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-mobile-alt"></i>
                  <div className="text">
                    <strong>Mobile Navigation That Frustrated Buyers</strong>
                    <p>
                      76% of traffic came from mobile, but the navigation menu
                      was nested and difficult to use on small screens, visitors
                      couldn't find what they were looking for and left before
                      reaching a product page
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-shopping-cart"></i>
                  <div className="text">
                    <strong>71% Cart Abandonment Rate</strong>
                    <p>
                      The checkout flow had unnecessary friction, too many
                      steps, no express payment options surfaced prominently,
                      and a cart drawer that provided no confidence or clarity
                      to hesitant buyers
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-home"></i>
                  <div className="text">
                    <strong>Homepage That Didn't Sell</strong>
                    <p>
                      The homepage had no clear value proposition, no social
                      proof above the fold, and a hero section that looked
                      identical to discount dropshipping stores, actively
                      undermining the brand's premium positioning
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-sitemap"></i>
                  <div className="text">
                    <strong>No Upsell Architecture Anywhere</strong>
                    <p>
                      No cross-sells on product pages, no bundle offers, no
                      post-purchase upsell, every transaction ended at exactly
                      one item with zero attempt to increase order value
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>

        <Cta />

        {/* ── Strategy Section ── */}
        <div className="case-details-content-wrapper2">
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-lightbulb"></i>
              </div>
              <h2>Our Strategy</h2>
            </div>
            <div className="strategy-intro">
              <p className="section-intro">
                A redesign is not just cosmetic. Done correctly, it is a
                complete reconstruction of every touchpoint between the brand
                and the buyer, from the first impression on the homepage to the
                final step of checkout. Our approach to ArcVault combined
                conversion architecture, brand design, and technical execution
                into a single 18-day rebuild. Every decision was made with one
                question in mind: does this move a visitor closer to buying?
              </p>
            </div>

            <div className="strategy-cards">
              <div className="strategy-card">
                <div className="card-number">01</div>
                <h3>
                  <i className="fas fa-search"></i> Conversion Audit &amp;
                  Redesign Blueprint
                </h3>
                <ul>
                  <li>
                    Ran a full audit of the existing store using session
                    recordings, heatmaps, and funnel analytics, mapping every
                    point where visitors dropped off and why
                  </li>
                  <li>
                    Benchmarked ArcVault against 5 top-performing competitors in
                    the premium lifestyle space to identify design and trust
                    gaps
                  </li>
                  <li>
                    Created a page-by-page redesign blueprint prioritizing
                    homepage, product pages, and checkout, the three areas
                    accounting for 91% of all conversion drop-off
                  </li>
                  <li>
                    Defined a new visual identity system: color palette, type
                    hierarchy, image treatment standards, and component library
                    before writing a single line of code
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">02</div>
                <h3>
                  <i className="fas fa-home"></i> Homepage Rebuilt to Convert
                </h3>
                <ul>
                  <li>
                    Replaced the generic hero section with a full-bleed brand
                    story layout leading with the core value proposition, social
                    proof count, and a single dominant CTA, all above the fold
                  </li>
                  <li>
                    Introduced a "As Seen In" press bar and a live star rating
                    aggregate directly on the homepage to establish authority
                    within the first 5 seconds of a visit
                  </li>
                  <li>
                    Built a curated bestseller section with conversion-optimized
                    product cards including price, rating, and a quick-add
                    button, no navigation required to start buying
                  </li>
                  <li>
                    Added a brand story section with founder photography and
                    mission statement to create emotional connection with
                    first-time visitors
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">03</div>
                <h3>
                  <i className="fas fa-box-open"></i> Product Pages That
                  Actually Close
                </h3>
                <ul>
                  <li>
                    Redesigned every product page with a structured layout:
                    gallery left, conversion elements right, name, rating,
                    price, key benefits, variant selector, add-to-cart, and
                    trust badges all above the fold on desktop and mobile
                  </li>
                  <li>
                    Built a tabbed information architecture below the fold
                    covering product details, materials, sizing, shipping, and
                    return policy, giving every hesitant buyer the answer they
                    needed without leaving the page
                  </li>
                  <li>
                    Introduced lifestyle photography sections showing products
                    in real-world context, replacing studio-only images that
                    felt sterile and unconvincing
                  </li>
                  <li>
                    Surfaced the top 8 verified reviews with photos directly on
                    the product page, above the description fold, where 80% of
                    visitors actually read
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">04</div>
                <h3>
                  <i className="fas fa-shield-alt"></i> Trust System Built Into
                  Every Page
                </h3>
                <ul>
                  <li>
                    Designed a sitewide trust bar displaying money-back
                    guarantee, free shipping threshold, secure checkout badge,
                    and average rating, present on every page above the footer
                  </li>
                  <li>
                    Built a dedicated brand credibility section featuring press
                    mentions, certifications, and customer milestone numbers to
                    establish authority at scale
                  </li>
                  <li>
                    Integrated real-time social proof notifications showing
                    recent purchases and live visitor counts on product pages to
                    create authentic buying momentum
                  </li>
                  <li>
                    Made the return and exchange policy a visible, one-click
                    accessible feature on every product page, removing the last
                    objection for first-time buyers
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">05</div>
                <h3>
                  <i className="fas fa-shopping-cart"></i> Checkout Streamlined
                  for Speed
                </h3>
                <ul>
                  <li>
                    Reduced the checkout from 4 steps to 2 by consolidating
                    contact, address, and shipping preference into a single
                    intelligent form with smart field autofill
                  </li>
                  <li>
                    Moved Shop Pay, Apple Pay, and Google Pay to the top of the
                    checkout page as the primary path, for returning customers
                    this reduced checkout time to under 20 seconds
                  </li>
                  <li>
                    Redesigned the cart drawer with a full order summary, trust
                    indicators, and a visible free shipping progress bar that
                    actively encouraged customers to add one more item
                  </li>
                  <li>
                    Fixed all mobile keyboard and input field behavior from
                    scratch, no more zoom-on-tap, no more misaligned fields, no
                    more keyboard covering the submit button
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">06</div>
                <h3>
                  <i className="fas fa-layer-group"></i> Revenue-Maximizing
                  Upsell Architecture
                </h3>
                <ul>
                  <li>
                    Built a "Pairs Well With" cross-sell module on every product
                    page matching complementary items by collection and use
                    case, increasing multi-product purchases by 38%
                  </li>
                  <li>
                    Introduced bundle offers directly on product pages with a
                    visible per-item discount, making the value of buying more
                    immediately clear
                  </li>
                  <li>
                    Added a post-purchase one-click upsell page offering a
                    time-sensitive offer on a complementary product, zero
                    re-entry of payment details required
                  </li>
                  <li>
                    Implemented a cart upsell triggered at 70% of the free
                    shipping threshold, consistently converting browsers into
                    higher-value buyers before they reached checkout
                  </li>
                </ul>
              </div>
            </div>
          </section>
        </div>

        {/* ── Results Showcase ── */}
        <section className="results-showcase">
          <div className="case-details-result-content-wrapper">
            <div className="results-header">
              <h2>
                <i className="fas fa-trophy"></i> The Results
              </h2>
              <p className="results-description-intro">
                Eighteen days after launch, ArcVault's store was an entirely
                different business. Same products. Same ad spend. The redesign
                alone doubled their conversion rate and pushed monthly revenue
                to a level the brand had never reached before. Their founder put
                it simply: "The old store was a ceiling. This one feels like
                there's no ceiling at all."
              </p>
            </div>

            <div className="metrics-grid">
              <div className="metric-card">
                <div className="case-details-metric-label">Conversion Rate</div>
                <div className="metric-comparison">
                  <span className="metric-before">2.0%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">4.1%</span>
                </div>
                <div className="improvement-badge">+105% Increase</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Cart Abandonment
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">71%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">29%</span>
                </div>
                <div className="improvement-badge">59% Reduction</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Avg. Order Value
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">$86</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">$121</span>
                </div>
                <div className="improvement-badge">+41% Higher AOV</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Monthly Revenue</div>
                <div className="metric-comparison">
                  <span className="metric-before">$31K</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">$91K</span>
                </div>
                <div className="improvement-badge">+193% Revenue Lift</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Bounce Rate</div>
                <div className="metric-comparison">
                  <span className="metric-before">58%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">24%</span>
                </div>
                <div className="improvement-badge">59% Reduction</div>
              </div>
            </div>
          </div>
        </section>
      </div>
      {/* <CustomerReviews /> */}
    </>
  );
};

export default ThirdCaseStory;
