import SEO, { serviceSchema } from "../SEO";
import { useEffect } from "react";
import Breadcrumb from "../Breadcrumb";
// import ServicesHero from "../ServicesHero";
import ConnectedServices from "../ConnectedServices";
import CustomerReviews from "../CustomerReviews";
// import Packages from "../Packages";
// import Process from "../Process";
// import Portfolio from "../Portfolio";
// import Testimonial from "../Testimonial";
import AboutCTA from "../AboutCTA";
import "../../styles/Services.css";

export default function Services() {
  useEffect(() => {
    // Intersection Observer (Blur Vanish Effect)
    const observerOptions = {
      threshold: 0.3,
      rootMargin: "0px 0px -100px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          setTimeout(() => {
            entry.target.classList.add("visible");
          }, 100);
        }
      });
    }, observerOptions);

    const blurElements = document.querySelectorAll(
      ".blur-vanish, .blur-vanish-left, .blur-vanish-right, .blur-vanish-scale, .stagger-item, .blur-glow, .floating-blur, .text-blur-reveal"
    );
    blurElements.forEach((el) => observer.observe(el));

    // Magnetic Hover Effect
    const magneticElements = document.querySelectorAll(".magnetic-effect");
    magneticElements.forEach((el) => {
      el.addEventListener("mousemove", function (e) {
        const rect = this.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        const centerX = rect.width / 2;
        const centerY = rect.height / 2;
        const rotateX = (y - centerY) / 10;
        const rotateY = (centerX - x) / 10;

        this.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.02)`;
      });

      el.addEventListener("mouseleave", function () {
        this.style.transform = "";
      });
    });

    // Ripple Effect for Buttons
    const buttons = document.querySelectorAll(
      ".btn-primary, .btn-secondary, .cta-button"
    );
    buttons.forEach((btn) => {
      btn.addEventListener("click", function (e) {
        const ripple = document.createElement("span");
        const rect = this.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height);
        const x = e.clientX - rect.left - size / 2;
        const y = e.clientY - rect.top - size / 2;

        ripple.style.cssText = `
          position: absolute;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.6);
          transform: scale(0);
          animation: ripple 0.6s linear;
          width: ${size}px;
          height: ${size}px;
          left: ${x}px;
          top: ${y}px;
          pointer-events: none;
        `;

        this.style.position = "relative";
        this.style.overflow = "hidden";
        this.appendChild(ripple);

        setTimeout(() => ripple.remove(), 600);
      });
    });

    // Floating Animation for Icons
    const serviceIcons = document.querySelectorAll(".service-icon");
    serviceIcons.forEach((icon, i) => {
      icon.style.animation = `float 3s ease-in-out infinite`;
      icon.style.animationDelay = `${i * 0.3}s`;
    });

    // Header Scroll + Hero Parallax
    const onScroll = () => {
      const scrolled = window.pageYOffset;
      const header = document.getElementById("header");

      if (header) {
        if (scrolled > 100) header.classList.add("scrolled");
        else header.classList.remove("scrolled");
      }

      const heroImage = document.querySelector(".hero-image");
      if (heroImage) {
        const speed = scrolled * 0.2;
        heroImage.style.transform = `translateY(${speed}px)`;
      }
    };

    window.addEventListener("scroll", onScroll);

    // Smooth Scroll for Anchor Links
    document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
      anchor.addEventListener("click", function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute("href"));
        if (target) {
          target.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
    });

    // Cleanup on unmount
    return () => {
      window.removeEventListener("scroll", onScroll);
      blurElements.forEach((el) => observer.unobserve(el));
    };
  }, []);

  return (
    <>
      <SEO title="Our Services" description="Comprehensive digital services — Shopify development, WordPress, mobile apps, custom software, data analytics, and UI/UX design. Premium solutions for growth-ready brands." path="/services" schema={serviceSchema("Digital Services", "Full-spectrum digital services for ambitious brands", "/services")} />
      <Breadcrumb title="Services" />
      {/* <ServicesHero /> */}
      <ConnectedServices ctaLabel="Let's Build Your Store" ctaLink="#booking" />
      {/* <Packages /> */}
      {/* <Process /> */}
      {/* <Portfolio /> */}
      <CustomerReviews />
      <AboutCTA />
    </>
  );
}
