import { FileText } from "lucide-react";
import { useState, useEffect } from "react";

/* ═══════════════════════════════════════════════════════════════
   FILTERED BLOG VIEW — Read-only, category-filtered blog
   Used inside service portfolio pages (Shopify, WordPress, etc.)
   No admin, no editor — just published posts filtered by category
   ═══════════════════════════════════════════════════════════════ */

function getApiBase() {
  return window.location.hostname === "localhost"
    ? "http://localhost:8081"
    : "/api";
}

const PLACEHOLDER_IMG =
  "https://cdn.shopify.com/s/files/1/0644/4086/0781/files/Shopify-webs-1.png?v=1765272625";

function FilteredBlogList({ categories, accentColor, onReadPost, onBack }) {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${getApiBase()}/blog-api.php?action=list&status=published`)
      .then((r) => r.json())
      .then((d) => {
        if (d.posts) {
          const filtered = d.posts.filter((p) =>
            categories.some((cat) =>
              p.category?.toLowerCase().includes(cat.toLowerCase()),
            ),
          );
          setPosts(filtered);
        }
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [categories]);

  return (
    <div
      style={{
        background: "#EDE9E3",
        minHeight: "100vh",
        fontFamily: "'DM Sans',sans-serif",
      }}
    >
      <section style={{ padding: "40px 28px 60px" }}>
        <div style={{ maxWidth: 900, margin: "0 auto" }}>
          <div
            className="filtered-blog-header"
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: 32,
            }}
          >
            <div>
              <h2 style={{ fontSize: 32, color: "#3D4A35", marginBottom: 6 }}>
                Latest Articles
              </h2>
              <p style={{ fontSize: 14, color: "#8A857E" }}>
                Insights, tips, and strategies from our team
              </p>
            </div>
            <button
              onClick={onBack}
              style={{
                padding: "8px 20px",
                borderRadius: 50,
                background: accentColor,
                color: "#fff",
                border: "none",
                fontSize: 13,
                fontWeight: 600,
                cursor: "pointer",
              }}
            >
              ← Back
            </button>
          </div>

          {loading ? (
            <p
              style={{
                textAlign: "center",
                color: "#8A857E",
                padding: "40px 0",
              }}
            >
              Loading articles...
            </p>
          ) : posts.length === 0 ? (
            <div
              style={{
                textAlign: "center",
                padding: "60px 20px",
                background: "#fff",
                borderRadius: 16,
              }}
            >
              <div
                style={{
                  marginBottom: 12,
                  display: "flex",
                  justifyContent: "center",
                }}
              >
                <FileText size={48} color="#2563eb" />
              </div>
              <h3
                style={{
                  fontSize: 18,
                  fontWeight: 700,
                  color: "#3D4A35",
                  marginBottom: 8,
                }}
              >
                No articles yet
              </h3>
              <p style={{ fontSize: 14, color: "#8A857E" }}>
                We're working on creating valuable content. Check back soon!
              </p>
            </div>
          ) : (
            <div style={{ display: "grid", gap: 20 }}>
              {posts.map((post) => (
                <div
                  key={post.slug}
                  onClick={() => onReadPost(post.slug)}
                  className="filtered-blog-card"
                  style={{
                    background: "#fff",
                    borderRadius: 16,
                    cursor: "pointer",
                    boxShadow: "0 2px 12px rgba(0,0,0,.04)",
                    transition: "all .3s",
                    border: "1px solid rgba(0,0,0,.04)",
                    display: "grid",
                    gridTemplateColumns: post.image ? "200px 1fr" : "1fr",
                    overflow: "hidden",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.transform = "translateY(-2px)";
                    e.currentTarget.style.boxShadow =
                      "0 8px 24px rgba(0,0,0,.08)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.transform = "";
                    e.currentTarget.style.boxShadow =
                      "0 2px 12px rgba(0,0,0,.04)";
                  }}
                >
                  {(post.image || PLACEHOLDER_IMG) && (
                    <div
                      style={{
                        width: "100%",
                        height: "100%",
                        minHeight: 140,
                        background: `url(${post.image || PLACEHOLDER_IMG}) center/cover no-repeat`,
                      }}
                    />
                  )}
                  <div
                    style={{
                      padding: "24px 28px",
                      display: "flex",
                      flexDirection: "column",
                      justifyContent: "center",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        justifyContent: "space-between",
                        alignItems: "center",
                        marginBottom: 8,
                      }}
                    >
                      <span
                        style={{
                          fontSize: 11,
                          fontWeight: 600,
                          padding: "2px 10px",
                          borderRadius: 20,
                          background: `${accentColor}15`,
                          color: accentColor,
                        }}
                      >
                        {post.category}
                      </span>
                      <span style={{ fontSize: 11, color: "#B5AFA8" }}>
                        {post.created_at
                          ? new Date(post.created_at).toLocaleDateString()
                          : ""}
                      </span>
                    </div>
                    <h3
                      style={{
                        fontSize: 18,
                        fontWeight: 700,
                        color: "#1a1a1a",
                        marginBottom: 6,
                        lineHeight: 1.3,
                      }}
                    >
                      {post.title}
                    </h3>
                    {post.excerpt && (
                      <p
                        style={{
                          fontSize: 13,
                          color: "#8A857E",
                          lineHeight: 1.6,
                          marginBottom: 8,
                          display: "-webkit-box",
                          WebkitLineClamp: 2,
                          WebkitBoxOrient: "vertical",
                          overflow: "hidden",
                        }}
                      >
                        {post.excerpt}
                      </p>
                    )}
                    <span
                      style={{
                        fontSize: 12,
                        color: accentColor,
                        fontWeight: 600,
                      }}
                    >
                      Read article →
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>
    </div>
  );
}

function FilteredBlogPost({ slug, accentColor, onBackToBlog }) {
  const [post, setPost] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch(`${getApiBase()}/blog-api.php?action=get&slug=${slug}`)
      .then((r) => r.json())
      .then((d) => {
        if (d.post) setPost(d.post);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [slug]);

  if (loading)
    return (
      <div
        style={{
          padding: "80px 28px",
          textAlign: "center",
          fontFamily: "'DM Sans',sans-serif",
        }}
      >
        Loading...
      </div>
    );
  if (!post)
    return (
      <div
        style={{
          padding: "80px 28px",
          textAlign: "center",
          fontFamily: "'DM Sans',sans-serif",
        }}
      >
        <h2>Article not found</h2>
        <button
          onClick={onBackToBlog}
          style={{
            marginTop: 16,
            padding: "10px 24px",
            borderRadius: 8,
            background: accentColor,
            color: "#fff",
            border: "none",
            cursor: "pointer",
          }}
        >
          Back to Articles
        </button>
      </div>
    );

  return (
    <div
      style={{
        background: "#EDE9E3",
        minHeight: "100vh",
        fontFamily: "'DM Sans',sans-serif",
      }}
    >
      <style>{`
        .sp-blog-content h2{font-size:22px;font-weight:700;color:#1a1a1a;margin:28px 0 12px;font-family:'Playfair Display',serif}
        .sp-blog-content h3{font-size:18px;font-weight:700;color:${accentColor};margin:20px 0 10px}
        .sp-blog-content p{font-size:15px;line-height:1.8;color:#5E5A54;margin:0 0 16px}
        .sp-blog-content ul,.sp-blog-content ol{margin:0 0 16px 20px;color:#5E5A54}
        .sp-blog-content li{font-size:14px;line-height:1.8;margin-bottom:6px}
        .sp-blog-content strong{color:#1a1a1a}
        .sp-blog-content a{color:${accentColor};text-decoration:underline}
        .sp-blog-content blockquote{border-left:3px solid ${accentColor};padding:12px 20px;margin:16px 0;background:#F8F6F2;border-radius:0 8px 8px 0}
      `}</style>
      <section style={{ padding: "40px 28px 80px" }}>
        <div style={{ maxWidth: 740, margin: "0 auto" }}>
          <button
            onClick={onBackToBlog}
            style={{
              padding: "8px 20px",
              borderRadius: 50,
              background: accentColor,
              color: "#fff",
              border: "none",
              fontSize: 13,
              fontWeight: 600,
              cursor: "pointer",
              marginBottom: 24,
            }}
          >
            ← All Articles
          </button>
          {/* Featured Image */}
          {(post.image || PLACEHOLDER_IMG) && (
            <div
              style={{
                width: "100%",
                height: 300,
                borderRadius: "20px 20px 0 0",
                background: `url(${post.image || PLACEHOLDER_IMG}) center/cover no-repeat`,
                marginBottom: -1,
              }}
            />
          )}
          <div
            style={{
              background: "#fff",
              borderRadius: post.image ? "0 0 20px 20px" : 20,
              padding: "44px 40px",
              boxShadow: "0 4px 30px rgba(0,0,0,.06)",
            }}
          >
            <span
              style={{
                display: "inline-block",
                padding: "4px 14px",
                borderRadius: 20,
                background: `${accentColor}15`,
                color: accentColor,
                fontSize: 12,
                fontWeight: 600,
                marginBottom: 14,
              }}
            >
              {post.category}
            </span>
            <h1
              style={{
                fontSize: "clamp(24px,3.5vw,36px)",
                color: "#1a1a1a",
                lineHeight: 1.2,
                marginBottom: 12,
              }}
            >
              {post.title}
            </h1>
            <div style={{ fontSize: 13, color: "#8A857E", marginBottom: 28 }}>
              By {post.author || "TechTCL"} ·{" "}
              {post.created_at
                ? new Date(post.created_at).toLocaleDateString()
                : ""}
            </div>
            <div
              className="sp-blog-content"
              dangerouslySetInnerHTML={{ __html: post.content }}
            />
            {post.tags && (
              <div
                style={{
                  marginTop: 32,
                  paddingTop: 20,
                  borderTop: "1px solid #E0DCD6",
                  display: "flex",
                  gap: 10,
                  flexWrap: "wrap",
                }}
              >
                {post.tags.split(",").map((t, i) => (
                  <span
                    key={i}
                    style={{
                      padding: "4px 12px",
                      borderRadius: 20,
                      background: `${accentColor}15`,
                      color: accentColor,
                      fontSize: 11,
                      fontWeight: 600,
                    }}
                  >
                    #{t.trim()}
                  </span>
                ))}
              </div>
            )}
          </div>
        </div>
      </section>
    </div>
  );
}

/* Main component with hash-based routing */
export default function FilteredBlogView({ categories, accentColor, onBack }) {
  const [view, setView] = useState("list");
  const [blogSlug, setBlogSlug] = useState("");

  useEffect(() => {
    const handleHash = () => {
      const hash = window.location.hash;
      if (hash.startsWith("#/blog/")) {
        setView("post");
        setBlogSlug(hash.replace("#/blog/", ""));
      } else if (hash === "#/blog") {
        setView("list");
      } else {
        setView("list");
      }
    };
    handleHash();
    window.addEventListener("hashchange", handleHash);
    return () => window.removeEventListener("hashchange", handleHash);
  }, []);

  const goList = () => {
    window.location.hash = "#/blog";
    setView("list");
    window.scrollTo(0, 0);
  };
  const goPost = (slug) => {
    window.location.hash = "#/blog/" + slug;
    window.scrollTo(0, 0);
  };
  const goBack = () => {
    window.location.hash = "";
    onBack();
  };

  if (view === "post")
    return (
      <FilteredBlogPost
        slug={blogSlug}
        accentColor={accentColor}
        onBackToBlog={goList}
      />
    );
  return (
    <FilteredBlogList
      categories={categories}
      accentColor={accentColor}
      onReadPost={goPost}
      onBack={goBack}
    />
  );
}
