import SEO from "../SEO";
import React from "react";
import "../../styles/PrivacyPolicy.css";
import Breadcrumb from "../Breadcrumb";

const PrivacyPolicy = () => {
  return (
    <>
      <Breadcrumb title="Privacy Policy" />
      <div className="privpol-container-wrapper">
        <div className="privpol-content-box">
          <main className="privpol-body-content">
            <p className="privpol-intro-text">
              At our Shopify agency, we are committed to protecting your privacy
              and ensuring the security of your personal information. This
              Privacy Policy explains how we collect, use, disclose, and
              safeguard your information when you use our services.
            </p>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">
                1. Information We Collect
              </h2>
              <p className="privpol-paragraph-text">
                We collect information that you provide directly to us when
                using our Shopify services, including:
              </p>
              <ul className="privpol-bullet-list">
                <li className="privpol-list-item">
                  Contact information (name, email address, phone number)
                </li>
                <li className="privpol-list-item">
                  Business information (company name, website URL, business
                  type)
                </li>
                <li className="privpol-list-item">
                  Shopify store credentials and access permissions
                </li>
                <li className="privpol-list-item">
                  Payment and billing information
                </li>
                <li className="privpol-list-item">
                  Communication records and support tickets
                </li>
              </ul>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">
                2. How We Use Your Information
              </h2>
              <p className="privpol-paragraph-text">
                We use the information we collect to:
              </p>
              <ul className="privpol-bullet-list">
                <li className="privpol-list-item">
                  Provide, maintain, and improve our Shopify services
                </li>
                <li className="privpol-list-item">
                  Process transactions and send related information
                </li>
                <li className="privpol-list-item">
                  Respond to your comments, questions, and customer service
                  requests
                </li>
                <li className="privpol-list-item">
                  Send technical notices, updates, and administrative messages
                </li>
                <li className="privpol-list-item">
                  Monitor and analyze trends, usage, and activities
                </li>
                <li className="privpol-list-item">
                  Detect, prevent, and address technical issues or fraudulent
                  activity
                </li>
              </ul>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">
                3. Information Sharing and Disclosure
              </h2>
              <p className="privpol-paragraph-text">
                We do not sell, trade, or rent your personal information to
                third parties. We may share your information only in the
                following circumstances:
              </p>
              <ul className="privpol-bullet-list">
                <li className="privpol-list-item">
                  With service providers who assist in our operations (e.g.,
                  hosting, analytics)
                </li>
                <li className="privpol-list-item">
                  With Shopify, as necessary to provide our services
                </li>
                <li className="privpol-list-item">
                  When required by law or to protect our rights
                </li>
                <li className="privpol-list-item">
                  With your explicit consent
                </li>
              </ul>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">4. Data Security</h2>
              <p className="privpol-paragraph-text">
                We implement appropriate technical and organizational measures
                to protect your personal information against unauthorized
                access, alteration, disclosure, or destruction. However, no
                method of transmission over the internet or electronic storage
                is completely secure, and we cannot guarantee absolute security.
              </p>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">5. Data Retention</h2>
              <p className="privpol-paragraph-text">
                We retain your personal information for as long as necessary to
                fulfill the purposes outlined in this Privacy Policy, unless a
                longer retention period is required or permitted by law. When we
                no longer need your information, we will securely delete or
                anonymize it.
              </p>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">6. Your Rights</h2>
              <p className="privpol-paragraph-text">
                Depending on your location, you may have the following rights
                regarding your personal information:
              </p>
              <ul className="privpol-bullet-list">
                <li className="privpol-list-item">
                  Access and receive a copy of your personal data
                </li>
                <li className="privpol-list-item">
                  Correct inaccurate or incomplete information
                </li>
                <li className="privpol-list-item">
                  Request deletion of your personal data
                </li>
                <li className="privpol-list-item">
                  Object to or restrict processing of your data
                </li>
                <li className="privpol-list-item">Data portability</li>
                <li className="privpol-list-item">
                  Withdraw consent at any time
                </li>
              </ul>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">
                7. Cookies and Tracking Technologies
              </h2>
              <p className="privpol-paragraph-text">
                We use cookies and similar tracking technologies to track
                activity on our website and store certain information. You can
                instruct your browser to refuse all cookies or to indicate when
                a cookie is being sent.
              </p>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">
                8. Third-Party Services
              </h2>
              <p className="privpol-paragraph-text">
                Our services may contain links to third-party websites or
                services, including Shopify. We are not responsible for the
                privacy practices of these third parties. We encourage you to
                review their privacy policies.
              </p>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">9. Children's Privacy</h2>
              <p className="privpol-paragraph-text">
                Our services are not intended for individuals under the age of
                18. We do not knowingly collect personal information from
                children. If you believe we have collected information from a
                child, please contact us immediately.
              </p>
            </section>

            <section className="privpol-section-block">
              <h2 className="privpol-section-heading">
                10. Changes to This Privacy Policy
              </h2>
              <p className="privpol-paragraph-text">
                We may update this Privacy Policy from time to time. We will
                notify you of any changes by posting the new Privacy Policy on
                this page and updating the "Last Updated" date. We encourage you
                to review this Privacy Policy periodically.
              </p>
            </section>

            <div className="privpol-contact-box">
              <h2 className="privpol-contact-title">Contact Us</h2>
              <p className="privpol-contact-text">
                If you have any questions about this Privacy Policy or our
                practices, please contact us at:
              </p>
              <p className="privpol-contact-text">
                Email:{" "}
                <a
                  href="mailto:support@techtcl.com"
                  className="privpol-email-link"
                >
                  support@techtcl.com
                </a>
              </p>
            </div>
          </main>
        </div>
      </div>
    </>
  );
};

export default PrivacyPolicy;
