import React, { useState, useEffect, useRef } from "react";
import "../styles/CaseStory.css";
import { Link } from "react-router-dom";
// import case_story_img from "../assets/dropshipping_store.jpg";
// import case1 from "../assets/Qozay-webs.png";
import {
  ArrowRight,
  // TrendingUp,
  Users,
  ShoppingCart,
  // Zap,
  // CheckCircle,
  // XCircle,
  TrendingDown,
  Clock,
  DollarSign,
  Target,
} from "lucide-react";
import CaseStoryGrid from "./CaseStoryGrid";

export default function CaseStudyBody() {
  const [selectedCategory, setSelectedCategory] = useState("all");

  const problems = [
    {
      icon: TrendingDown,
      question: "Low conversion rates eating your profits?",
      description:
        "Visitors browse but don't buy. Your traffic isn't turning into revenue.",
      highlight: "conversion",
    },
    {
      icon: ShoppingCart,
      question: "Cart abandonment killing your sales?",
      description:
        "Customers add items but leave before checkout. Money left on the table.",
      highlight: "abandonment",
    },
    {
      icon: Users,
      question: "Struggling to attract the right customers?",
      description:
        "Getting traffic, but not the buyers who actually want your products.",
      highlight: "targeting",
    },
    {
      icon: Clock,
      question: "Spending hours but seeing no growth?",
      description:
        "Working hard on your store but revenue stays flat month after month.",
      highlight: "growth",
    },
    {
      icon: DollarSign,
      question: "Ad spend not bringing returns?",
      description:
        "Pouring money into ads with little to show for it. Your ROI is disappointing.",
      highlight: "roi",
    },
    {
      icon: Target,
      question: "Can't figure out what's wrong?",
      description:
        "You know something's off, but you can't pinpoint exactly what needs fixing.",
      highlight: "diagnosis",
    },
  ];


  // const filteredCaseStudies =
  //   selectedCategory === "all"
  //     ? caseStudies
  //     : caseStudies.filter((cs) => cs.category === selectedCategory);

  const heroSectionRef = useRef(null);
  const mouseFollowerRef = useRef(null);
  const statsRef = useRef(null);
  const [counters, setCounters] = useState({
    stories: 0,
    growth: 0,
    satisfaction: 0,
  });
  const [hasAnimated, setHasAnimated] = useState(false);

  // Mouse follower effect
  useEffect(() => {
    const heroSection = heroSectionRef.current;
    const mouseFollower = mouseFollowerRef.current;

    if (!heroSection || !mouseFollower) return;

    const handleMouseMove = (e) => {
      const rect = heroSection.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      mouseFollower.style.left = x + "px";
      mouseFollower.style.top = y + "px";
    };

    heroSection.addEventListener("mousemove", handleMouseMove);

    return () => {
      heroSection.removeEventListener("mousemove", handleMouseMove);
    };
  }, []);

  // Counter animation effect
  useEffect(() => {
    const statsElement = statsRef.current; // Copy ref to variable

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting && !hasAnimated) {
            setHasAnimated(true);
            animateCounters();
          }
        });
      },
      { threshold: 0.5 }
    );

    if (statsElement) {
      observer.observe(statsElement);
    }

    return () => {
      if (statsElement) {
        observer.unobserve(statsElement);
      }
    };
  }, [hasAnimated]);

  const animateCounters = () => {
    const duration = 2000; // 2 seconds
    const steps = 60;
    const stepDuration = duration / steps;

    const targets = {
      stories: 50,
      growth: 300,
      satisfaction: 98,
    };

    let currentStep = 0;

    const interval = setInterval(() => {
      currentStep++;
      const progress = currentStep / steps;

      setCounters({
        stories: Math.floor(targets.stories * progress),
        growth: Math.floor(targets.growth * progress),
        satisfaction: Math.floor(targets.satisfaction * progress),
      });

      if (currentStep >= steps) {
        clearInterval(interval);
        setCounters(targets); // Set final values
      }
    }, stepDuration);
  };

  return (
    <div className="case-study-page">
      {/* Hero Section */}
      <section className="case-hero-section" ref={heroSectionRef}>
        {/* Mouse-following glow effect */}
        <div className="case-mouse-follower" ref={mouseFollowerRef}></div>

        {/* Animated background elements */}
        <div className="case-bg-overlay">
          <div className="case-bg-circle-1"></div>
          <div className="case-bg-circle-2"></div>
        </div>

        {/* Dot pattern overlay */}
        <div className="case-dot-pattern"></div>
        {/* Content */}
        <div className="case-hero-content">
          {/* Badge */}
          <div className="case-hero-badge">
            <svg
              className="case-badge-icon"
              fill="currentColor"
              viewBox="0 0 20 20"
            >
              <path
                fillRule="evenodd"
                d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 2.812c.051.643.304 1.254.723 1.745a3.066 3.066 0 010 3.976 3.066 3.066 0 00-.723 1.745 3.066 3.066 0 01-2.812 2.812 3.066 3.066 0 00-1.745.723 3.066 3.066 0 01-3.976 0 3.066 3.066 0 00-1.745-.723 3.066 3.066 0 01-2.812-2.812 3.066 3.066 0 00-.723-1.745 3.066 3.066 0 010-3.976 3.066 3.066 0 00.723-1.745 3.066 3.066 0 012.812-2.812zm7.44 5.252a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                clipRule="evenodd"
              />
            </svg>
            <span className="case-badge-text">CASE STUDIES</span>
          </div>

          {/* Main heading */}
          <h1 className="case-hero-title">
            Proven Results,
            {/* <br /> */}
            <span className="case-gradient-text"> Real Growth</span>
          </h1>

          {/* Description */}
          <p className="case-hero-description">
            We don't just build stores — we build success stories.
          </p>
          <p className="case-hero-subdescription">
            Your growth is our mission.
          </p>

          <div className="cta-buttons">
            <Link className="btn-primary blur-vanish-scale visible">
              View Success Stories
            </Link>
            <Link className="btn-secondary blur-vanish-scale visible case-btn-secondary">
              Learn More
            </Link>
          </div>

          {/* Stats row */}
          <div className="case-stats-container" ref={statsRef}>
            <div className="case-stat-item">
              <div className="case-stat-number">{counters.stories}+</div>
              <div className="case-stat-label">Success Stories</div>
            </div>
            <div className="case-stat-item">
              <div className="case-stat-number">{counters.growth}%</div>
              <div className="case-stat-label">Avg Growth</div>
            </div>
            <div className="case-stat-item">
              <div className="case-stat-number">{counters.satisfaction}%</div>
              <div className="case-stat-label">Client Satisfaction</div>
            </div>
          </div>
        </div>
      </section>

      {/* Problems Section */}
      <section className="shopify-problems-section-wrapper">
        <div className="shopify-problems-container">
          {/* Header */}
          <div className="shopify-problems-header">
            <h2 className="shopify-problems-title">Sound Familiar?</h2>
            <p className="shopify-problems-subtitle">
              You're not alone. These are the most common challenges Shopify
              store owners face every day.
            </p>
          </div>

          {/* Problems Grid */}
          <div className="shopify-problems-grid">
            {problems.map((problem, index) => {
              const Icon = problem.icon;
              return (
                <div key={index} className="shopify-problem-card">
                  {/* Icon with accent */}
                  <div className="shopify-problem-icon-wrapper">
                    <div className="shopify-problem-icon-bg">
                      <Icon size={28} />
                    </div>
                  </div>

                  {/* Question as headline */}
                  <h3 className="shopify-problem-question">
                    {problem.question}
                  </h3>

                  {/* Description */}
                  <p className="shopify-problem-description">
                    {problem.description}
                  </p>

                  {/* Subtle hover indicator */}
                  <div className="shopify-problem-hover-indicator" />
                </div>
              );
            })}
          </div>
        </div>
      </section>

      {/* Case Studies Section */}
      <CaseStoryGrid />

      {/* Before & After Section */}
      {/* <section className="before-after-section">
        <div className="container">
          <div className="section-header">
            <h2>The TechTCL Transformation</h2>
            <p>From struggling store to thriving business</p>
          </div>

          <div className="comparison-wrapper">
            <div className="comparison-column before-column">
              <div className="column-header">
                <XCircle size={32} />
                <h3>Before</h3>
              </div>
              <ul className="comparison-list">
                {beforeAfter.before.map((item, idx) => {
                  const Icon = item.icon;
                  return (
                    <li key={idx}>
                      <Icon size={20} />
                      <span>{item.label}</span>
                    </li>
                  );
                })}
              </ul>
            </div>

            <div className="comparison-divider">
              <div className="divider-line"></div>
              <div className="divider-icon">→</div>
            </div>

            <div className="comparison-column after-column">
              <div className="column-header">
                <CheckCircle size={32} />
                <h3>After</h3>
              </div>
              <ul className="comparison-list">
                {beforeAfter.after.map((item, idx) => {
                  const Icon = item.icon;
                  return (
                    <li key={idx}>
                      <Icon size={20} />
                      <span>{item.label}</span>
                    </li>
                  );
                })}
              </ul>
            </div>
          </div>

          <div className="cta-wrapper">
            <h3>Ready to Write Your Success Story?</h3>
            <button className="cta-button">Get Started Today</button>
          </div>
        </div>
      </section> */}
    </div>
  );
}
