import { ExternalLink } from "lucide-react";
import React, { useState } from "react";
import {
  FaInstagram,
  FaLinkedinIn,
  FaRedditAlien,
  FaWhatsapp,
  FaTiktok,
} from "react-icons/fa";
import { FaThreads, FaXTwitter } from "react-icons/fa6";
import { FiCheck, FiCopy, FiFacebook } from "react-icons/fi";
import { href, Link } from "react-router-dom";

const ServiceBottomSidebar = ({
  caseStories = [],
  shareUrl,
  shareTitle = "Check out this amazing service!",
}) => {
  const [copied, setCopied] = useState(false);

  const currentUrl =
    shareUrl || (typeof window !== "undefined" ? window.location.href : "");
  const encodedUrl = encodeURIComponent(currentUrl);
  const encodedTitle = encodeURIComponent(shareTitle);

  const socialLinks = [
    {
      icon: <FiFacebook size={24} className="blog-social-icon" />,
      className: "blog-details-tag-item blog-details-social",
      href: `https://www.facebook.com/sharer/sharer.php?u=${encodedUrl}`,
      label: "Facebook",
    },
    {
      icon: <FaInstagram size={24} className="blog-social-icon" />,
      className: "blog-details-tag-item social-instagram blog-details-social",
      href: `https://www.instagram.com/techtcl/`,
      label: "Instagram",
    },
    {
      icon: <FaLinkedinIn size={24} className="blog-social-icon" />,
      className: "blog-details-tag-item social-linkedin blog-details-social",
      href: `https://www.linkedin.com/sharing/share-offsite/?url=${encodedUrl}`,
      label: "LinkedIn",
    },
    {
      icon: <FaTiktok size={24} className="blog-social-icon" />,
      className: "blog-details-tag-item social-tiktok blog-details-social",
      href: `https://www.tiktok.com/@techtcl`,
      label: "TikTok",
    },
    // {
    //   icon: <FaXTwitter size={24} className="blog-social-icon" />,
    //   className: "blog-details-tag-item social-twitter blog-details-social",
    //   href: `https://twitter.com/intent/tweet?url=${encodedUrl}&text=${encodedTitle}`,
    //   label: "Twitter/X",
    // },
    // {
    //   icon: <FaRedditAlien size={26} className="blog-social-icon" />,
    //   className: "blog-details-tag-item social-reddit blog-details-social",
    //   href: `https://www.reddit.com/submit?url=${encodedUrl}&title=${encodedTitle}`,
    //   label: "Reddit",
    // },
    // {
    //   icon: <FaThreads size={24} className="blog-social-icon" />,
    //   className: "blog-details-tag-item social-threads blog-details-social",
    //   href: `https://www.threads.net/intent/post?text=${encodedTitle}%20${encodedUrl}`,
    //   label: "Threads",
    // },
  ];

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(currentUrl);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch {
      // fallback
      const el = document.createElement("textarea");
      el.value = currentUrl;
      document.body.appendChild(el);
      el.select();
      document.execCommand("copy");
      document.body.removeChild(el);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="service-bottom-sidebar">
      {caseStories.length > 0 && (
        <div className="blog-details-sidebar-section">
          <h3 className="blog-details-sidebar-title">Relevant Case Stories</h3>

          {caseStories.map((story, idx) => (
            <div className="news-item" key={idx}>
              <img
                src={story.logo}
                alt={story.altText}
                className="relevantCase-logo"
              />
              <Link to={story.link} className="case-story-link">
                <div className="news-content">
                  <h4 className="news-title">{story.title}</h4>
                  <p className="news-date">{story.date}</p>
                </div>
              </Link>
            </div>
          ))}
        </div>
      )}

      {/* <div className="contact-card">
        <div className="contact-card-content">
          <div className="phone-icon">
            <FaWhatsapp />
          </div>
          <h3>Need help? Talk to expert</h3>
          <p>Contact us for any advice</p>
        </div>
      </div> */}

      <div className="blog-details-social-section blog-details-sidebar-section">
        <h3 className="blog-details-social-title">Share in Socials</h3>
        <div className="tag-cloud">
          {socialLinks.map((social) => (
            <a
              key={social.label}
              href={social.href}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={`Share on ${social.label}`}
              title={`Share on ${social.label}`}
              // className="blog-details-tag-item blog-details-social"
              className={social.className}
            >
              <span>{social.icon}</span>
            </a>
          ))}

          {/* Copy Link Button */}
          <span
            className="blog-details-tag-item"
            onClick={handleCopy}
            title={copied ? "Copied!" : "Copy Link"}
            style={{ cursor: "pointer" }}
          >
            {copied ? (
              <ExternalLink size={24} className="blog-social-icon" />
            ) : (
              <ExternalLink size={24} className="blog-social-icon" />
            )}
          </span>
        </div>
      </div>
    </div>
  );
};

export default ServiceBottomSidebar;
