import React, { useEffect } from "react";
import "../../styles/CaseStoryDetails.css";
import CustomerReviews from "../CustomerReviews";
import Cta from "../Cta";
import { FaShopify } from "react-icons/fa6";
import { MdLocationPin } from "react-icons/md";
import { Sparkles } from "lucide-react";

const SixthCaseStory = () => {
  useEffect(() => {
    // ===== Blur Vanish Effect =====
    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          if (entry.target.id === "missionProgress") {
            setTimeout(() => {
              entry.target.classList.add("animate");
            }, 500);
          }
        }
      });
    }, observerOptions);

    const blurElements = document.querySelectorAll(
      ".blur-vanish, .blur-vanish-left, .blur-vanish-right, .blur-vanish-scale, .stagger-item, .blur-glow, .floating-blur, .text-blur-reveal",
    );
    blurElements.forEach((el) => observer.observe(el));

    const progressBar = document.getElementById("missionProgress");
    if (progressBar) observer.observe(progressBar);

    // ===== Hover Effects =====
    const hoverElements = document.querySelectorAll(".enhanced-hover");
    hoverElements.forEach((el) => {
      el.addEventListener("mouseenter", function () {
        this.style.transform = "translateY(-8px) scale(1.02)";
        this.style.boxShadow = "0 20px 40px rgba(92, 39, 254, 0.15)";
        this.style.filter = "drop-shadow(0 8px 16px rgba(0, 0, 0, 0.1))";
      });
      el.addEventListener("mouseleave", function () {
        this.style.transform = "";
        this.style.boxShadow = "";
        this.style.filter = "";
      });
    });

    // ===== Dynamic Cursor =====
    const interactiveElements = document.querySelectorAll(
      ".btn-primary, .cta-button, .enhanced-hover",
    );
    interactiveElements.forEach((el) => {
      el.addEventListener("mouseenter", () => {
        document.body.style.cursor = "pointer";
      });
      el.addEventListener("mouseleave", () => {
        document.body.style.cursor = "default";
      });
    });

    // ===== Ripple Effect =====
    const buttons = document.querySelectorAll(".btn-primary, .cta-button");
    buttons.forEach((btn) => {
      btn.addEventListener("click", function (e) {
        const ripple = document.createElement("span");
        const rect = this.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height);
        const x = e.clientX - rect.left - size / 2;
        const y = e.clientY - rect.top - size / 2;

        ripple.style.cssText = `
          position: absolute;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.6);
          transform: scale(0);
          animation: ripple 0.6s linear;
          width: ${size}px;
          height: ${size}px;
          left: ${x}px;
          top: ${y}px;
          pointer-events: none;
        `;

        this.style.position = "relative";
        this.style.overflow = "hidden";
        this.appendChild(ripple);
        setTimeout(() => ripple.remove(), 600);
      });
    });

    const style = document.createElement("style");
    style.textContent = `
      @keyframes ripple {
        to { transform: scale(4); opacity: 0; }
      }
    `;
    document.head.appendChild(style);

    // ===== Scroll Effects =====
    const onScroll = () => {
      const scrolled = window.pageYOffset;
      const header = document.getElementById("header");
      if (scrolled > 100) {
        header?.classList.add("scrolled");
      } else {
        header?.classList.remove("scrolled");
      }
      const heroImage = document.querySelector(".hero-image");
      if (heroImage) {
        heroImage.style.transform = `translateY(${scrolled * 0.3}px)`;
      }
    };
    window.addEventListener("scroll", onScroll);

    // ===== Smooth Anchor Scroll =====
    const anchors = document.querySelectorAll('a[href^="#"]');
    anchors.forEach((a) => {
      a.addEventListener("click", function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute("href"));
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    // ===== Floating Avatars =====
    const avatars = document.querySelectorAll(".team-avatar");
    avatars.forEach((avatar, i) => {
      avatar.style.animation = "float 3s ease-in-out infinite";
      avatar.style.animationDelay = `${i * 0.5}s`;
    });

    const floatingStyle = document.createElement("style");
    floatingStyle.textContent = `
      @keyframes float {
        0%, 100% { transform: translateY(0px); }
        50% { transform: translateY(-10px); }
      }
    `;
    document.head.appendChild(floatingStyle);

    // ===== Mousemove 3D Cards =====
    const cards = document.querySelectorAll(
      ".client-card, .team-card, .vision-item, .why-card",
    );
    document.addEventListener("mousemove", (e) => {
      cards.forEach((card) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
          const centerX = rect.width / 2;
          const centerY = rect.height / 2;
          const rotateX = (y - centerY) / 10;
          const rotateY = (centerX - x) / 10;
          card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.02)`;
        } else {
          card.style.transform = "";
        }
      });
    });

    // ===== Cleanup =====
    return () => {
      window.removeEventListener("scroll", onScroll);
      observer.disconnect();
    };
  }, []);

  return (
    <>
      <div className="case-story-container">
        {/* ── Hero Banner ── */}
        <section className="case-details-hero-banner">
          <div className="case-details-hero-pattern"></div>
          <div className="case-details-container">
            <div className="case-details-hero-content">
              <div className="case-study-badge">
                <i className="fas fa-star"></i>
                SUCCESS STORY
              </div>
              <h1 className="melissa-hero-title">
                Their Designer Nailed the Figma, But No Developer Could Build It
                Accurately
              </h1>
              <p>
                A premium beauty brand had a stunning Figma design, but
                developers couldn’t execute it properly. We converted it into a
                pixel-perfect Shopify store with flawless mobile performance and
                a 91 PageSpeed score on launch.
              </p>
              <div className="case-details-hero-stats">
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">100%</span>
                  <span className="case-details-stat-label">
                    FIGMA ACCURACY
                  </span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">91</span>
                  <span className="case-details-stat-label">
                    PAGESPEED SCORE
                  </span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">3.2x</span>
                  <span className="case-details-stat-label">
                    CONVERSION LIFT
                  </span>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* ── Client Overview Card ── */}
        <div className="case-details-container">
          <div className="case-details-client-card">
            <div className="case-details-client-header">
              <div className="case-details-client-logo">
                <div className="case-details-client-logo">
                  <img
                    src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/Lumisoft.webp?v=1771989909"
                    alt="Lumisoft Logo"
                  />
                </div>
              </div>
              <div className="case-details-client-info">
                <h2>Lumisoft Beauty</h2>
                <div className="case-details-client-meta">
                  <div className="case-details-meta-item">
                    <Sparkles size={16} />
                    Premium Beauty &amp; Skincare Brand
                  </div>
                  <div className="case-details-meta-item">
                    <FaShopify />
                    Shopify Platform
                  </div>
                  <div className="case-details-meta-item">
                    <MdLocationPin />
                    United States
                  </div>
                </div>
              </div>
            </div>
            <div className="quick-facts">
              <div className="fact-box">
                <div className="label">Project Duration</div>
                <div className="value">10 Days</div>
              </div>
              <div className="fact-box">
                <div className="label">Primary Issue</div>
                <div className="value">Inaccurate Dev Conversions</div>
              </div>
              <div className="fact-box">
                <div className="label">Industry</div>
                <div className="value">Beauty &amp; Skincare / DTC</div>
              </div>
              <div className="fact-box">
                <div className="label">SERVICES PROVIDED</div>
                <div className="value">Figma to Shopify Conversion</div>
              </div>
            </div>
          </div>
        </div>

        {/* ── Content Wrapper ── */}
        <div className="case-details-content-wrapper">
          {/* ── Challenge Section ── */}
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-exclamation-triangle"></i>
              </div>
              <h2>The Breaking Point</h2>
            </div>
            <p className="section-intro">
              Lumisoft Beauty had done everything right on the design side.
              Their in-house designer had spent three months crafting a
              stunning, detail-rich Figma file, every spacing value deliberate,
              every font pairing intentional, every section built to position
              the brand at the premium end of the beauty market. It was exactly
              the kind of store that converts cold traffic into loyal customers.
              The only problem was getting it live.
            </p>
            <p className="section-intro">
              Their first developer delivered a store that looked approximately
              right at a glance but fell apart under scrutiny, wrong font
              weights, inconsistent spacing, components that didn't match the
              Figma at any breakpoint, and a mobile experience that bore no
              resemblance to the mobile frames the designer had built. Their
              second developer got closer on desktop but introduced a new set of
              performance problems: a PageSpeed score of 31, a 6.4-second load
              time, and a checkout that had never been tested on a real mobile
              device. Two failed builds, months of delay, and a brand that still
              wasn't live. They came to us to do it right, once, with no
              compromises on accuracy or performance.
            </p>

            <div className="challenge-grid">
              <div className="challenge-visual">
                <div className="speed-indicator">
                  <div className="speed-circle">
                    <div className="speed-inner">
                      <span className="speed-score">31</span>
                      <span className="speed-label">Speed Score</span>
                    </div>
                  </div>
                </div>
                <div className="problem-tag">
                  <i className="fas fa-times-circle"></i> Two Failed Builds
                </div>
              </div>

              <div className="challenge-list">
                <div className="challenge-item">
                  <i className="fas fa-pencil-ruler"></i>
                  <div className="text">
                    <strong>Figma Design Never Matched in Code</strong>
                    <p>
                      Two separate developers had attempted the conversion, both
                      delivered stores with incorrect spacing, wrong typography
                      weights, misaligned components, and section layouts that
                      deviated from the Figma on every breakpoint
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-tachometer-alt"></i>
                  <div className="text">
                    <strong>PageSpeed Score of 31 on the Last Build</strong>
                    <p>
                      The closest attempt to accuracy came at the cost of
                      performance, unoptimized images, render-blocking scripts,
                      and theme bloat pushed load time to 6.4 seconds, actively
                      damaging SEO rankings and ad quality scores
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-mobile-alt"></i>
                  <div className="text">
                    <strong>Mobile Frames Were Completely Ignored</strong>
                    <p>
                      The Figma file contained fully designed mobile frames for
                      every page, but neither developer had implemented them.
                      The mobile experience was an auto-scaled version of the
                      desktop, not the intentional mobile design the brand had
                      paid to create
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-clock"></i>
                  <div className="text">
                    <strong>Months of Delay With No Live Store</strong>
                    <p>
                      Two development cycles had passed without a successful
                      launch, months of lost revenue, delayed marketing
                      campaigns, and a growing gap between the brand's design
                      vision and what actually existed in Shopify
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-layer-group"></i>
                  <div className="text">
                    <strong>Custom Sections With No Shopify Equivalent</strong>
                    <p>
                      The Figma design included several bespoke sections, an
                      interactive ingredient map, a before/after slider, and a
                      custom routine builder, that had no native Shopify theme
                      equivalent and required custom Liquid development from
                      scratch
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-shopping-cart"></i>
                  <div className="text">
                    <strong>Checkout Never Tested or Optimized</strong>
                    <p>
                      Both previous builds had focused entirely on the
                      storefront and neglected the checkout entirely, no express
                      payment options, no trust signals at the payment step, and
                      a cart experience that had never been QA tested on a
                      physical mobile device
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>

        <Cta />

        {/* ── Strategy Section ── */}
        <div className="case-details-content-wrapper2">
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-lightbulb"></i>
              </div>
              <h2>Our Strategy</h2>
            </div>
            <div className="strategy-intro">
              <p className="section-intro">
                Pixel-perfect Figma to Shopify conversion is not just a
                development task, it is a precision craft that demands equal
                command of design systems, Shopify's Liquid templating
                architecture, and front-end performance engineering. Our
                approach to Lumisoft Beauty combined a thorough Figma audit
                before writing a single line of code, a component-by-component
                build process with continuous side-by-side accuracy checks, and
                a performance-first technical foundation that ensured the
                finished store was as fast as it was faithful to the original
                design.
              </p>
            </div>

            <div className="strategy-cards">
              <div className="strategy-card">
                <div className="card-number">01</div>
                <h3>
                  <i className="fas fa-search"></i> Figma Audit &amp; Build
                  Planning
                </h3>
                <ul>
                  <li>
                    Conducted a full audit of the Figma file before writing any
                    code, cataloguing every component, design token, breakpoint,
                    interaction, and animation across all desktop, tablet, and
                    mobile frames
                  </li>
                  <li>
                    Identified all custom sections with no native Shopify
                    equivalent and scoped each one for custom Liquid development
                    , no shortcuts, no substitutions, no "close enough"
                    compromises
                  </li>
                  <li>
                    Extracted the complete design token system from Figma: every
                    color variable, type scale, spacing unit, border radius, and
                    shadow value, translated directly into CSS custom properties
                    before the first component was built
                  </li>
                  <li>
                    Created a component build order prioritizing the most
                    complex custom sections first so that any technical
                    challenges were surfaced early, with time to resolve them
                    before the deadline
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">02</div>
                <h3>
                  <i className="fas fa-code"></i> Pixel-Perfect Liquid
                  Development
                </h3>
                <ul>
                  <li>
                    Built every section and component as a custom Shopify Liquid
                    snippet, no reliance on theme defaults that would require
                    overriding and introduce style conflicts. Every element was
                    coded to spec from the Figma file directly
                  </li>
                  <li>
                    Used a side-by-side browser overlay method throughout
                    development, the Figma frame rendered at 50% opacity over
                    the live build in the browser, making any spacing,
                    alignment, or sizing deviation immediately visible and
                    correctable in real time
                  </li>
                  <li>
                    Matched every typographic detail precisely: font family,
                    weight, size, line height, letter spacing, and color, across
                    all six text styles defined in the Figma design system, at
                    every responsive breakpoint
                  </li>
                  <li>
                    Built all interactive states, hover, active, focus, and
                    loading, exactly as specified in the Figma prototype,
                    including transition durations and easing curves
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">03</div>
                <h3>
                  <i className="fas fa-layer-group"></i> Custom Section
                  Development
                </h3>
                <ul>
                  <li>
                    Built the interactive ingredient map section from scratch in
                    Liquid and vanilla JavaScript, hotspot markers linked to
                    ingredient detail panels, fully responsive with a redesigned
                    touch-friendly layout on mobile
                  </li>
                  <li>
                    Developed a native before/after image slider using CSS and a
                    lightweight JavaScript implementation, no heavy third-party
                    library, no app dependency, no performance overhead on the
                    product page
                  </li>
                  <li>
                    Coded the custom skincare routine builder as a Shopify
                    section with step-by-step logic, product recommendations per
                    skin type, and direct add-to-cart functionality from within
                    the routine flow
                  </li>
                  <li>
                    All three custom sections were built as reusable Shopify
                    theme sections with a full schema, the client can edit
                    content, swap products, and update copy directly from the
                    Shopify customizer without touching any code
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">04</div>
                <h3>
                  <i className="fas fa-mobile-alt"></i> Full Mobile Frame
                  Implementation
                </h3>
                <ul>
                  <li>
                    Implemented every mobile frame from the Figma file as a
                    distinct responsive layout, not a scaled-down desktop view,
                    but the intentional mobile design the brand had built,
                    applied at the correct breakpoints
                  </li>
                  <li>
                    Rebuilt the mobile navigation as a full-screen overlay menu
                    matching the Figma mobile prototype exactly, smooth
                    open/close animation, correct type scale, and thumb-zone
                    touch targets on all interactive elements
                  </li>
                  <li>
                    Optimized all product page layouts for mobile specifically:
                    swipeable image gallery, collapsed ingredient details,
                    sticky add-to-cart bar, and a before/after slider redesigned
                    for portrait touch interaction
                  </li>
                  <li>
                    QA tested across 16 real device and browser combinations
                    before delivery, iPhone SE, iPhone 15 Pro, Samsung Galaxy
                    S23, iPad, and desktop across Chrome, Safari, Firefox, and
                    Edge
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">05</div>
                <h3>
                  <i className="fas fa-tachometer-alt"></i> Performance
                  Engineering
                </h3>
                <ul>
                  <li>
                    Optimized every image during the build, WebP format, correct
                    srcset responsive sizing, lazy loading below the fold, and
                    explicit width/height attributes to eliminate Cumulative
                    Layout Shift throughout the store
                  </li>
                  <li>
                    Implemented inline critical CSS for above-the-fold content
                    on the homepage and product pages, first paint in under 0.8
                    seconds, LCP score of 1.4 seconds on launch day
                  </li>
                  <li>
                    Deferred all non-critical JavaScript with async and defer
                    attributes, analytics, chat widget, and review scripts load
                    after the page is fully rendered and interactive
                  </li>
                  <li>
                    Loaded only the two font weights used in the design system,
                    self-hosted with font-display swap, zero invisible text
                    flash, zero layout shift from font loading at any breakpoint
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">06</div>
                <h3>
                  <i className="fas fa-shopping-cart"></i> Cart, Trust Badges
                  &amp; QA
                </h3>
                <ul>
                  <li>
                    Rebuilt the cart drawer to match the Figma design exactly,
                    product thumbnails, quantity controls, subtotal, and a free
                    shipping progress bar, all styled to the brand's design
                    system without a single pixel out of place
                  </li>
                  <li>
                    Added a trust badge strip directly on every product page
                    above the add-to-cart button, money-back guarantee, secure
                    checkout, and free returns, giving hesitant buyers the
                    confidence they need before they ever reach checkout
                  </li>
                  <li>
                    Applied Lumisoft's brand logo to the Shopify checkout header
                    , the only native customization Shopify's checkout allows,
                    keeping brand consistency visible through to the final
                    payment step
                  </li>
                  <li>
                    Ran a final end-to-end QA pass covering every user flow:
                    browse, add to cart, checkout, order confirmation, and
                    post-purchase, verified on physical devices across iOS and
                    Android before handoff
                  </li>
                </ul>
              </div>
            </div>
          </section>
        </div>

        {/* ── Results Showcase ── */}
        <section className="results-showcase">
          <div className="case-details-result-content-wrapper">
            <div className="results-header">
              <h2>
                <i className="fas fa-trophy"></i> The Results
              </h2>
              <p className="results-description-intro">
                Ten days after kickoff, Lumisoft Beauty was live, with a store
                that matched their Figma design at every breakpoint, on every
                device, down to the last pixel. After two failed builds and
                months of delay, the brand finally had the store their design
                had always deserved. Their lead designer's response on delivery:
                "I've been doing this for eight years. I have never seen a
                developer hand back a build that looks exactly like the file.
                This is the first time."
              </p>
            </div>

            <div className="metrics-grid">
              <div className="metric-card">
                <div className="case-details-metric-label">PageSpeed Score</div>
                <div className="metric-comparison">
                  <span className="metric-before">31</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">91</span>
                </div>
                <div className="improvement-badge">+193% Improvement</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Load Time</div>
                <div className="metric-comparison">
                  <span className="metric-before">6.4s</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">1.3s</span>
                </div>
                <div className="improvement-badge">80% Faster</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Figma Accuracy</div>
                <div className="metric-comparison">
                  <span className="metric-before">~60%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">100%</span>
                </div>
                <div className="improvement-badge">Pixel Perfect</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Conversion Rate</div>
                <div className="metric-comparison">
                  <span className="metric-before">0.9%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">3.1%</span>
                </div>
                <div className="improvement-badge">3.2x Lift</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Mobile Score</div>
                <div className="metric-comparison">
                  <span className="metric-before">24</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">88</span>
                </div>
                <div className="improvement-badge">+267% Better</div>
              </div>
            </div>
          </div>
        </section>
      </div>
      {/* <CustomerReviews /> */}
    </>
  );
};

export default SixthCaseStory;
