import React, { useEffect } from "react";
import "../../styles/CaseStoryDetails.css";
import CustomerReviews from "../CustomerReviews";
import Cta from "../Cta";
import { FaShopify } from "react-icons/fa6";
import { MdLocationPin } from "react-icons/md";
import { Shirt } from "lucide-react";

const FourthCaseStory = () => {
  useEffect(() => {
    // ===== Blur Vanish Effect =====
    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          if (entry.target.id === "missionProgress") {
            setTimeout(() => {
              entry.target.classList.add("animate");
            }, 500);
          }
        }
      });
    }, observerOptions);

    const blurElements = document.querySelectorAll(
      ".blur-vanish, .blur-vanish-left, .blur-vanish-right, .blur-vanish-scale, .stagger-item, .blur-glow, .floating-blur, .text-blur-reveal",
    );
    blurElements.forEach((el) => observer.observe(el));

    const progressBar = document.getElementById("missionProgress");
    if (progressBar) observer.observe(progressBar);

    // ===== Hover Effects =====
    const hoverElements = document.querySelectorAll(".enhanced-hover");
    hoverElements.forEach((el) => {
      el.addEventListener("mouseenter", function () {
        this.style.transform = "translateY(-8px) scale(1.02)";
        this.style.boxShadow = "0 20px 40px rgba(92, 39, 254, 0.15)";
        this.style.filter = "drop-shadow(0 8px 16px rgba(0, 0, 0, 0.1))";
      });
      el.addEventListener("mouseleave", function () {
        this.style.transform = "";
        this.style.boxShadow = "";
        this.style.filter = "";
      });
    });

    // ===== Dynamic Cursor =====
    const interactiveElements = document.querySelectorAll(
      ".btn-primary, .cta-button, .enhanced-hover",
    );
    interactiveElements.forEach((el) => {
      el.addEventListener("mouseenter", () => {
        document.body.style.cursor = "pointer";
      });
      el.addEventListener("mouseleave", () => {
        document.body.style.cursor = "default";
      });
    });

    // ===== Ripple Effect =====
    const buttons = document.querySelectorAll(".btn-primary, .cta-button");
    buttons.forEach((btn) => {
      btn.addEventListener("click", function (e) {
        const ripple = document.createElement("span");
        const rect = this.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height);
        const x = e.clientX - rect.left - size / 2;
        const y = e.clientY - rect.top - size / 2;

        ripple.style.cssText = `
          position: absolute;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.6);
          transform: scale(0);
          animation: ripple 0.6s linear;
          width: ${size}px;
          height: ${size}px;
          left: ${x}px;
          top: ${y}px;
          pointer-events: none;
        `;

        this.style.position = "relative";
        this.style.overflow = "hidden";
        this.appendChild(ripple);
        setTimeout(() => ripple.remove(), 600);
      });
    });

    const style = document.createElement("style");
    style.textContent = `
      @keyframes ripple {
        to { transform: scale(4); opacity: 0; }
      }
    `;
    document.head.appendChild(style);

    // ===== Scroll Effects =====
    const onScroll = () => {
      const scrolled = window.pageYOffset;
      const header = document.getElementById("header");
      if (scrolled > 100) {
        header?.classList.add("scrolled");
      } else {
        header?.classList.remove("scrolled");
      }
      const heroImage = document.querySelector(".hero-image");
      if (heroImage) {
        heroImage.style.transform = `translateY(${scrolled * 0.3}px)`;
      }
    };
    window.addEventListener("scroll", onScroll);

    // ===== Smooth Anchor Scroll =====
    const anchors = document.querySelectorAll('a[href^="#"]');
    anchors.forEach((a) => {
      a.addEventListener("click", function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute("href"));
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    // ===== Floating Avatars =====
    const avatars = document.querySelectorAll(".team-avatar");
    avatars.forEach((avatar, i) => {
      avatar.style.animation = "float 3s ease-in-out infinite";
      avatar.style.animationDelay = `${i * 0.5}s`;
    });

    const floatingStyle = document.createElement("style");
    floatingStyle.textContent = `
      @keyframes float {
        0%, 100% { transform: translateY(0px); }
        50% { transform: translateY(-10px); }
      }
    `;
    document.head.appendChild(floatingStyle);

    // ===== Mousemove 3D Cards =====
    const cards = document.querySelectorAll(
      ".client-card, .team-card, .vision-item, .why-card",
    );
    document.addEventListener("mousemove", (e) => {
      cards.forEach((card) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
          const centerX = rect.width / 2;
          const centerY = rect.height / 2;
          const rotateX = (y - centerY) / 10;
          const rotateY = (centerX - x) / 10;
          card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.02)`;
        } else {
          card.style.transform = "";
        }
      });
    });

    // ===== Cleanup =====
    return () => {
      window.removeEventListener("scroll", onScroll);
      observer.disconnect();
    };
  }, []);

  return (
    <>
      <div className="case-story-container">
        {/* ── Hero Banner ── */}
        <section className="case-details-hero-banner">
          <div className="case-details-hero-pattern"></div>
          <div className="case-details-container">
            <div className="case-details-hero-content">
              <div className="case-study-badge">
                <i className="fas fa-star"></i>
                SUCCESS STORY
              </div>
              <h1 className="melissa-hero-title">
                Their Shopify store had traffic, but revenue was leaking.
              </h1>
              <p>
                A growing fashion brand had traffic but no conversions, no
                funnel, upsells, or checkout strategy. In 16 days, we integrated
                CheckoutChamp and built a complete sales funnel, turning clicks
                into compounding revenue machine.
              </p>
              <div className="case-details-hero-stats">
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">341%</span>
                  <span className="case-details-stat-label">REVENUE LIFT</span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">4.6%</span>
                  <span className="case-details-stat-label">
                    FUNNEL CONVERSION RATE
                  </span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">67%</span>
                  <span className="case-details-stat-label">
                    HIGHER AVG ORDER VALUE
                  </span>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* ── Client Overview Card ── */}
        <div className="case-details-container">
          <div className="case-details-client-card">
            <div className="case-details-client-header">
              <div className="case-details-client-logo">
                <div className="case-details-client-logo">
                  <img
                    src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/Driftline_Co_53e40a81-0de9-4c09-830f-e537f63f805c.webp?v=1771990021"
                    alt="Driftline Co. Logo"
                  />
                </div>
              </div>
              <div className="case-details-client-info">
                <h2>Driftline Co.</h2>
                <div className="case-details-client-meta">
                  <div className="case-details-meta-item">
                    <Shirt size={16} />
                    Contemporary Streetwear Brand
                  </div>
                  <div className="case-details-meta-item">
                    <FaShopify />
                    Shopify + CheckoutChamp
                  </div>
                  <div className="case-details-meta-item">
                    <MdLocationPin />
                    United States
                  </div>
                </div>
              </div>
            </div>
            <div className="quick-facts">
              <div className="fact-box">
                <div className="label">Project Duration</div>
                <div className="value">16 Days</div>
              </div>
              <div className="fact-box">
                <div className="label">Primary Issue</div>
                <div className="value">No Funnel, No Structure</div>
              </div>
              <div className="fact-box">
                <div className="label">Industry</div>
                <div className="value">Streetwear / DTC Fashion</div>
              </div>
              <div className="fact-box">
                <div className="label">SERVICES PROVIDED</div>
                <div className="value">Sales Funnel Integration</div>
              </div>
            </div>
          </div>
        </div>

        {/* ── Content Wrapper ── */}
        <div className="case-details-content-wrapper">
          {/* ── Challenge Section ── */}
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-exclamation-triangle"></i>
              </div>
              <h2>The Breaking Point</h2>
            </div>
            <p className="section-intro">
              Driftline Co. had everything a growing fashion brand needs on
              paper, a distinctive product line, a loyal social following, and a
              paid ad strategy that was consistently bringing in thousands of
              visitors every week. But their revenue refused to grow in
              proportion to their traffic. Their Shopify store was operating as
              a passive catalog, not an active selling machine. Visitors
              arrived, browsed, and left. There was no funnel guiding them
              toward a purchase. No structured checkout path built for
              conversion. No upsell flow capturing additional revenue after the
              first sale. And no post-purchase sequence keeping customers coming
              back.
            </p>
            <p className="section-intro">
              At a conversion rate of 1.3% and an average order value of $78,
              Driftline was generating a fraction of what their traffic was
              actually worth. Every day without a proper sales funnel was
              another day of paying for clicks that went nowhere. The fix wasn't
              more ads, it was connecting their Shopify store to a purpose-built
              sales funnel through CheckoutChamp, transforming their entire
              buyer journey from click to repeat purchase.
            </p>

            <div className="challenge-grid">
              <div className="challenge-visual">
                <div className="speed-indicator">
                  <div className="speed-circle">
                    <div className="speed-inner">
                      <span className="speed-score">1.3%</span>
                      <span className="speed-label">CVR</span>
                    </div>
                  </div>
                </div>
                <div className="problem-tag">
                  <i className="fas fa-times-circle"></i> No Funnel Structure
                </div>
              </div>

              <div className="challenge-list">
                <div className="challenge-item">
                  <i className="fas fa-random"></i>
                  <div className="text">
                    <strong>No Structured Sales Funnel</strong>
                    <p>
                      Traffic landed directly on the Shopify store homepage with
                      no dedicated landing page, no guided path to purchase, and
                      no conversion-optimized entry point, every visitor was
                      left to find their own way or leave
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-shopping-cart"></i>
                  <div className="text">
                    <strong>74% Cart Abandonment Rate</strong>
                    <p>
                      The native Shopify checkout had no optimized flow, no
                      express payment options surfaced at the right moment, and
                      no recovery mechanism for the 3 in 4 buyers who added to
                      cart and vanished
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-arrow-up"></i>
                  <div className="text">
                    <strong>Zero Post-Purchase Upsell Flow</strong>
                    <p>
                      Every completed order ended the moment the confirmation
                      page loaded. There was no one-click upsell offer, no order
                      bump, no post-purchase sequence, the most profitable
                      moment in the buyer journey was being wasted completely
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-unlink"></i>
                  <div className="text">
                    <strong>
                      Disconnected Ad Traffic With No Funnel Match
                    </strong>
                    <p>
                      Paid ad campaigns were sending cold traffic to generic
                      collection pages, no dedicated landing pages matched to
                      specific ad creative, no message continuity, no
                      single-focus conversion path that aligned with what the ad
                      promised
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-redo"></i>
                  <div className="text">
                    <strong>No Repeat Purchase Mechanism</strong>
                    <p>
                      First-time buyers had no structured path back to the
                      store. No post-purchase email sequence, no loyalty offer,
                      no retargeting funnel, customer lifetime value was limited
                      to a single transaction
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-chart-bar"></i>
                  <div className="text">
                    <strong>No Funnel Visibility or Attribution</strong>
                    <p>
                      There was no way to see where buyers were dropping off,
                      which ad sets were driving real revenue versus empty
                      clicks, or what the actual cost per acquisition was at
                      each stage of the purchase journey
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>

        <Cta />

        {/* ── Strategy Section ── */}
        <div className="case-details-content-wrapper2">
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-lightbulb"></i>
              </div>
              <h2>Our Strategy</h2>
            </div>
            <div className="strategy-intro">
              <p className="section-intro">
                We didn't change what Driftline was selling. We changed how
                their entire buyer journey was structured. Our approach was to
                integrate CheckoutChamp as the conversion engine sitting between
                their ad traffic and their Shopify backend, building a complete
                funnel infrastructure that captured, converted, and maximized
                every visitor their ads were already paying for. The Shopify
                store remained the inventory and fulfillment hub while
                CheckoutChamp handled the selling, the upsells, and the checkout
                experience end to end.
              </p>
            </div>

            <div className="strategy-cards">
              <div className="strategy-card">
                <div className="card-number">01</div>
                <h3>
                  <i className="fas fa-plug"></i> CheckoutChamp &amp; Shopify
                  Integration
                </h3>
                <ul>
                  <li>
                    Connected CheckoutChamp directly to Driftline's Shopify
                    store via API, inventory, product data, and order
                    fulfillment all synced in real time with zero manual
                    reconciliation needed
                  </li>
                  <li>
                    Configured CheckoutChamp as the primary checkout processor
                    while Shopify continued handling fulfillment, inventory
                    management, and post-purchase logistics, the best of both
                    platforms working together
                  </li>
                  <li>
                    Set up full funnel tracking with UTM passthrough so every
                    sale could be attributed back to its specific ad set,
                    audience, and creative, giving Driftline accurate ROAS data
                    for the first time
                  </li>
                  <li>
                    Integrated payment processing through CheckoutChamp
                    supporting all major cards, Shop Pay, Apple Pay, and Google
                    Pay, reducing checkout abandonment from the very first day
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">02</div>
                <h3>
                  <i className="fas fa-filter"></i> Dedicated Landing Pages per
                  Ad Campaign
                </h3>
                <ul>
                  <li>
                    Built 4 dedicated CheckoutChamp landing pages matched
                    precisely to Driftline's top-performing ad campaigns, same
                    visual language, same offer, same hook, eliminating the
                    message mismatch that was killing post-click conversions
                  </li>
                  <li>
                    Each landing page was engineered with a single focus: move
                    the visitor to the next step in the funnel. No navigation
                    menu, no distractions, no exit routes, just the product, the
                    proof, and the CTA
                  </li>
                  <li>
                    Structured each page with the AIDA framework: attention hook
                    above the fold, product benefits and social proof in the
                    middle, urgency and risk reversal before the CTA
                  </li>
                  <li>
                    A/B tested headline variants and hero image treatments
                    across all 4 pages during the first week post-launch,
                    locking in the highest-converting version of each by day 10
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">03</div>
                <h3>
                  <i className="fas fa-bolt"></i> High-Converting Checkout Flow
                  Build
                </h3>
                <ul>
                  <li>
                    Replaced the native Shopify checkout with a
                    CheckoutChamp-powered 2-step checkout, contact and payment
                    on step one, shipping confirmation on step two, reducing
                    time to purchase by 58%
                  </li>
                  <li>
                    Added an order bump directly on the checkout page offering a
                    complementary item at a discounted bundle price, a single
                    checkbox addition that increased AOV on 31% of all completed
                    orders
                  </li>
                  <li>
                    Surfaced express checkout options as the primary payment
                    path with card entry as secondary, for returning customers
                    and mobile shoppers this single change cut checkout
                    completion time in half
                  </li>
                  <li>
                    Built a visible trust bar into the checkout frame displaying
                    the money-back guarantee, secure payment badge, and
                    estimated delivery window, reducing checkout drop-off at the
                    payment step by 44%
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">04</div>
                <h3>
                  <i className="fas fa-arrow-circle-up"></i> One-Click
                  Post-Purchase Upsell Sequence
                </h3>
                <ul>
                  <li>
                    Built a 2-step post-purchase upsell sequence triggered
                    immediately after order confirmation, the highest-intent
                    moment in the entire customer journey, when a buyer has
                    already committed and their guard is fully down
                  </li>
                  <li>
                    Upsell 1: a matching accessory or complementary item at 30%
                    off, framed as an exclusive post-purchase offer only
                    available in the next 10 minutes, accepted by 28% of all
                    buyers, zero additional checkout required
                  </li>
                  <li>
                    Upsell 2: a second core product at a bundle discount, shown
                    only to customers who accepted the first upsell, adding an
                    average of $47 to those orders with a single additional
                    click
                  </li>
                  <li>
                    Downsell path built for customers who declined both upsells:
                    a softer offer for a lower-priced accessory, recovering
                    revenue from buyers who wanted more but weren't ready for
                    the full-price upsell
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">05</div>
                <h3>
                  <i className="fas fa-envelope-open-text"></i> Post-Purchase
                  Retention Funnel
                </h3>
                <ul>
                  <li>
                    Built a 5-email post-purchase sequence triggered from
                    CheckoutChamp on order confirmation, order acknowledgment,
                    shipping update, style tips featuring related products, a
                    review request, and a 7-day loyalty offer
                  </li>
                  <li>
                    Configured a 14-day abandoned cart retargeting sequence for
                    visitors who reached checkout but did not complete their
                    purchase, recovering 19% of abandoned carts through email
                    and SMS follow-up
                  </li>
                  <li>
                    Integrated a 30-day win-back sequence for customers who had
                    not repurchased, offering a personalized product
                    recommendation with a limited loyalty discount, driving a
                    23% repeat purchase rate within the first 60 days
                  </li>
                  <li>
                    All customer data captured through CheckoutChamp synced back
                    to Shopify automatically, keeping the full customer record,
                    purchase history, and LTV data in one place
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">06</div>
                <h3>
                  <i className="fas fa-chart-line"></i> Full Funnel Analytics
                  &amp; Attribution
                </h3>
                <ul>
                  <li>
                    Set up a complete funnel dashboard in CheckoutChamp showing
                    real-time conversion rates at every stage, landing page,
                    checkout step one, checkout step two, upsell one, and upsell
                    two, giving the team full visibility for the first time
                  </li>
                  <li>
                    Configured UTM-based attribution so every order could be
                    traced back to its exact ad set, audience segment, and
                    creative, enabling Driftline to cut underperforming ad spend
                    and double down on what was actually driving revenue
                  </li>
                  <li>
                    Built a weekly performance report tracking cost per
                    acquisition, revenue per visitor, funnel drop-off rates, and
                    upsell take rates, replacing guesswork with a data-driven
                    growth system
                  </li>
                  <li>
                    Integrated CheckoutChamp's split-testing suite to run
                    continuous CRO experiments on landing pages and checkout
                    copy, the funnel gets more efficient every week
                    automatically
                  </li>
                </ul>
              </div>
            </div>
          </section>
        </div>

        {/* ── Results Showcase ── */}
        <section className="results-showcase">
          <div className="case-details-result-content-wrapper">
            <div className="results-header">
              <h2>
                <i className="fas fa-trophy"></i> The Results
              </h2>
              <p className="results-description-intro">
                Sixteen days after the CheckoutChamp funnel went live, Driftline
                Co. was operating a completely different business. The same ad
                spend. The same products. The same Shopify store running in the
                background. But now every visitor entered a structured,
                conversion-optimized journey designed to maximize the value of
                each click. Their founder described it best: "We were treating
                our store like a shop window. Now it works like a salesperson
                that never sleeps."
              </p>
            </div>

            <div className="metrics-grid">
              <div className="metric-card">
                <div className="case-details-metric-label">
                  Funnel Conversion Rate
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">1.3%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">4.6%</span>
                </div>
                <div className="improvement-badge">+254% Increase</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Cart Abandonment
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">74%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">31%</span>
                </div>
                <div className="improvement-badge">58% Reduction</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Avg. Order Value
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">$78</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">$130</span>
                </div>
                <div className="improvement-badge">+67% Higher AOV</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Monthly Revenue</div>
                <div className="metric-comparison">
                  <span className="metric-before">$19K</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">$84K</span>
                </div>
                <div className="improvement-badge">+341% Revenue Lift</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Repeat Purchase Rate
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">4%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">23%</span>
                </div>
                <div className="improvement-badge">+475% Improvement</div>
              </div>
            </div>
          </div>
        </section>
      </div>
      {/* <CustomerReviews /> */}
    </>
  );
};

export default FourthCaseStory;
