export default function SocialProof() {
  const [active, setActive] = useState(0);
  const [isVisible, setIsVisible] = useState(false);
  const sectionRef = useRef(null);
  const timerRef = useRef(null);

  // Auto-rotate
  useEffect(() => {
    timerRef.current = setInterval(() => {
      setActive((p) => (p + 1) % REVIEWS.length);
    }, 5000);
    return () => clearInterval(timerRef.current);
  }, []);

  const goTo = (i) => {
    setActive(i);
    clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      setActive((p) => (p + 1) % REVIEWS.length);
    }, 5000);
  };

  const goPrev = () => goTo((active - 1 + REVIEWS.length) % REVIEWS.length);
  const goNext = () => goTo((active + 1) % REVIEWS.length);

  // Intersection Observer
  useEffect(() => {
    const obs = new IntersectionObserver(
      ([e]) => {
        if (e.isIntersecting) setIsVisible(true);
      },
      { threshold: 0.15 },
    );
    if (sectionRef.current) obs.observe(sectionRef.current);
    return () => obs.disconnect();
  }, []);

  return (
    <section
      className="social-proof-main"
      ref={sectionRef}
      style={{
        padding: "90px 20px",
        background: "linear-gradient(135deg, #2563eb 0%, #1e3c72 100%)",
        position: "relative",
        overflow: "hidden",
        opacity: isVisible ? 1 : 0,
        transform: isVisible ? "translateY(0)" : "translateY(30px)",
        transition: "all 0.8s ease",
      }}
    >
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: "rgba(0,0,0,.05)",
          zIndex: 0,
        }}
      />

      <div
        style={{
          maxWidth: 860,
          margin: "0 auto",
          position: "relative",
          zIndex: 1,
        }}
      >
        {/* Header */}
        <div style={{ textAlign: "center", marginBottom: 48 }}>
          <span
            style={{
              fontSize: 12,
              letterSpacing: 3,
              color: "rgba(255,255,255,.4)",
              textTransform: "uppercase",
              fontWeight: 700,
            }}
          >
            CLIENT REVIEWS
          </span>
          <h2
            className="cr-credibility-title"
            style={{
              fontSize: "clamp(28px,4vw,42px)",
              color: "#fff",
              marginTop: 8,
              lineHeight: 1.2,
            }}
          >
            What Our Clients Say About
            <br /> Working With TechTCL
          </h2>
        </div>

        {/* Review Card */}
        <div style={{ position: "relative", minHeight: 280 }}>
          {REVIEWS.map((review, i) => (
            <div
              className="cs-review-card"
              key={i}
              style={{
                position: i === active ? "relative" : "absolute",
                top: 0,
                left: 0,
                right: 0,
                opacity: i === active ? 1 : 0,
                transform: i === active ? "translateY(0)" : "translateY(15px)",
                transition: "all .6s ease",
                pointerEvents: i === active ? "auto" : "none",
                background: "rgba(255,255,255,.08)",
                borderRadius: 22,
                border: "1px solid rgba(255,255,255,.12)",
                padding: "44px 40px",
                backdropFilter: "blur(10px)",
              }}
            >
              {/* Stars */}
              <div
                style={{
                  display: "flex",
                  justifyContent: "center",
                  gap: 4,
                  // marginBottom: 20,
                }}
              >
                {[...Array(5)].map((_, j) => (
                  <span key={j} style={{ color: "#F5D060", fontSize: 20 }}>
                    ★
                  </span>
                ))}
              </div>

              {/* Quote */}
              <p
                style={{
                  fontSize: "clamp(14px,2vw,18px)",
                  fontStyle: "italic",
                  lineHeight: 1.8,
                  color: "#fff",
                  marginBottom: 28,
                  textAlign: "center",
                  maxWidth: 680,
                  marginLeft: "auto",
                  marginRight: "auto",
                }}
              >
                "{review.text}"
              </p>

              {/* Attribution */}
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 16,
                }}
              >
                <div className="sp-review-image"
                  style={{
                    width: 64,
                    height: 64,
                    borderRadius: "50%",
                    background: "rgba(96,165,250,.15)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 16,
                    fontWeight: 700,
                    color: "#60a5fa",
                    border: "2px solid rgba(96,165,250,.3)",
                    overflow: "hidden",
                    objectFit: "cover",
                  }}
                >
                  {/* {review.name
                    .split(" ")
                    .map((w) => w[0])
                    .join("")} */}
                  <img style={{width: "100%", height: "100%"}} src={review.avatar} alt={review.name} />
                </div>
                <div style={{ textAlign: "left" }}>
                  <div style={{ fontSize: 15, fontWeight: 700, color: "#fff" }}>
                    {review.name}
                  </div>
                  <div style={{ fontSize: 12, color: "rgba(255,255,255,.5)" }}>
                    {review.role}, {review.company}
                  </div>
                  <div
                    style={{
                      fontSize: 12,
                      color: "#60a5fa",
                      fontWeight: 600,
                      marginTop: 2,
                    }}
                  >
                    Result: {review.result}
                  </div>
                </div>
              </div>
            </div>
          ))}

          {/* Arrows */}
          <button
            onClick={goPrev}
            style={{
              position: "absolute",
              left: -20,
              top: "50%",
              transform: "translateY(-50%)",
              width: 42,
              height: 42,
              borderRadius: "50%",
              background: "rgba(255,255,255,.1)",
              border: "1px solid rgba(255,255,255,.2)",
              color: "#fff",
              fontSize: 20,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "all .3s",
              backdropFilter: "blur(6px)",
            }}
            onMouseEnter={(e) =>
              (e.currentTarget.style.background = "rgba(255,255,255,.2)")
            }
            onMouseLeave={(e) =>
              (e.currentTarget.style.background = "rgba(255,255,255,.1)")
            }
          >
            ‹
          </button>
          <button
            onClick={goNext}
            style={{
              position: "absolute",
              right: -20,
              top: "50%",
              transform: "translateY(-50%)",
              width: 42,
              height: 42,
              borderRadius: "50%",
              background: "rgba(255,255,255,.1)",
              border: "1px solid rgba(255,255,255,.2)",
              color: "#fff",
              fontSize: 20,
              cursor: "pointer",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              transition: "all .3s",
              backdropFilter: "blur(6px)",
            }}
            onMouseEnter={(e) =>
              (e.currentTarget.style.background = "rgba(255,255,255,.2)")
            }
            onMouseLeave={(e) =>
              (e.currentTarget.style.background = "rgba(255,255,255,.1)")
            }
          >
            ›
          </button>
        </div>

        {/* Dots */}
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: 6,
            marginTop: 28,
          }}
        >
          {REVIEWS.map((_, i) => (
            <button
              key={i}
              onClick={() => goTo(i)}
              style={{
                width: i === active ? 28 : 8,
                height: 8,
                borderRadius: 8,
                border: "none",
                cursor: "pointer",
                background: i === active ? "#60a5fa" : "rgba(255,255,255,.2)",
                transition: "all .3s",
              }}
            />
          ))}
        </div>
      </div>
    </section>
  );
}
