import React, { useState } from "react";
import "../../styles/ServiceDetails.css";

const CommonFAQSection = ({ content = [] }) => {
  const [openFaq, setOpenFaq] = useState(0);

  return (
    <div className="faq-section desktop-only-faqs">
      <h2>Frequently Asked Questions</h2>
      <div className="service-faq-list">
        {content.map((faq, idx) => (
          <div key={idx} className="faq-item">
            <div
              className={`faq-question ${openFaq === idx ? "active" : ""}`}
              onClick={() => setOpenFaq(openFaq === idx ? -1 : idx)}
            >
              <span>{faq.q}</span>
              <span className={`faq-arrow ${openFaq === idx ? "active" : ""}`}>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  viewBox="0 0 24 24"
                  width="16"
                  height="16"
                >
                  <path d="M12 17.414 3.293 8.707l1.414-1.414L12 14.586l7.293-7.293 1.414 1.414L12 17.414z" />
                </svg>
              </span>
            </div>
            <div className={`faq-answer ${openFaq === idx ? "active" : ""}`}>
              <p>{faq.a}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default CommonFAQSection;
