import React from "react";
import "../styles/WhatHappensNext.css";
import { Link } from "react-router-dom";

const WhatHappensNext = () => {
  const steps = [
    {
      icon: (
        <svg viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth="2">
          <rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect>
          <line x1="16" y1="2" x2="16" y2="6"></line>
          <line x1="8" y1="2" x2="8" y2="6"></line>
          <line x1="3" y1="10" x2="21" y2="10"></line>
          <path d="M8 14h.01M12 14h.01M16 14h.01M8 18h.01M12 18h.01M16 18h.01"></path>
        </svg>
      ),
      title: "Schedule a discovery call with us.",
    },
    {
      icon: (
        <svg viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth="2">
          <path d="M12 20h9"></path>
          <path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"></path>
        </svg>
      ),
      title: "Provide your project details in a brief.",
    },
    {
      icon: (
        <svg viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth="2">
          <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path>
          <circle cx="9" cy="7" r="4"></circle>
          <path d="M23 21v-2a4 4 0 0 0-3-3.87"></path>
          <path d="M16 3.13a4 4 0 0 1 0 7.75"></path>
        </svg>
      ),
      title: "Our team will start working on your landing page.",
    },
  ];

  return (
    <div className="ttcl-whn-container">
      <div className="ttcl-whn-wrapper">
        <h2 className="ttcl-whn-title">What Happens Next</h2>

        <div className="ttcl-whn-steps">
          {steps.map((step, index) => (
            <React.Fragment key={index}>
              <div className="ttcl-whn-step">
                <div className="ttcl-whn-icon-wrapper">{step.icon}</div>
                <h3 className="ttcl-whn-step-title">{step.title}</h3>
              </div>
              {index < steps.length - 1 && (
                <div className="ttcl-whn-arrow">
                  <svg viewBox="0 0 24 24">
                    <line x1="5" y1="12" x2="19" y2="12"></line>
                    <polyline points="12 5 19 12 12 19"></polyline>
                  </svg>
                </div>
              )}
            </React.Fragment>
          ))}
        </div>

        <div className="ttcl-whn-cta">
          <Link className="btn-primary blur-vanish-scale visible">
            Book a Free Consultation Now
          </Link>
        </div>
      </div>
    </div>
  );
};

export default WhatHappensNext;
