import { CalendarDays, MessageCircleMore } from "lucide-react";
import React, { useState } from "react";
import "./ServicesContent.css";

const ServiceContact = ({ serviceName = "Web Development" }) => {
  const [activePanel, setActivePanel] = useState("message");

  const handleWhatsApp = () => {
    const phoneNumber = "8801837127779";
    const message = encodeURIComponent(
      `Hi TechTCL! I'm interested in your ${serviceName} service. I'd love to discuss my project.`,
    );
    window.open(`https://wa.me/${phoneNumber}?text=${message}`, "_blank");
  };

  const handleFormSubmit = (e) => {
    e.preventDefault();
    alert("Message sent successfully!");
    setActivePanel(null);
  };

  const togglePanel = (panel) => {
    setActivePanel((prev) => (prev === panel ? null : panel));
  };

  return (
    <div className="sc-wrapper">
      <h2 className="sc-heading">Get Started Today</h2>
      <p className="sc-subheading">Choose how you'd like to connect with us</p>

      <div className="sc-button-row">
        {/* 1. Book Appointment */}
        <button
          className={`sc-action-btn sc-btn-calendar${activePanel === "booking" ? " sc-action-btn--active" : ""}`}
          onClick={() => togglePanel("booking")}
        >
          <span className="sc-btn-icon">
            <CalendarDays size={18} />
          </span>
          <span className="sc-btn-label">Book an Appointment</span>
          <span className="sc-btn-arrow">
            {activePanel === "booking" ? "▲" : "▼"}
          </span>
        </button>

        {/* 2. Send Message */}
        <button
          className={`sc-action-btn sc-btn-message${activePanel === "message" ? " sc-action-btn--active" : ""}`}
          onClick={() => togglePanel("message")}
        >
          <span className="sc-btn-icon">
            <MessageCircleMore size={18} />
          </span>
          <span className="sc-btn-label">Send Message</span>
          <span className="sc-btn-arrow">
            {activePanel === "message" ? "▲" : "▼"}
          </span>
        </button>

        {/* 3. Instant Message (WhatsApp) */}
        <button
          className="sc-action-btn sc-btn-whatsapp"
          onClick={handleWhatsApp}
        >
          <span className="sc-btn-icon">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
              <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z" />
            </svg>
          </span>
          <span className="sc-btn-label">Instant Message</span>
          <span className="sc-btn-arrow sc-btn-arrow--hidden">→</span>
        </button>
      </div>

      {/* Booking Panel */}
      {activePanel === "booking" && (
        <div className="sc-panel">
          <div className="sc-panel-header">
            <span>
              {" "}
              <CalendarDays size={18} /> Schedule a Meeting
            </span>
            <button
              className="sc-close-btn"
              onClick={() => setActivePanel(null)}
            >
              ✕
            </button>
          </div>
          <div className="sc-calendar-wrapper">
            <iframe
              src="https://calendar.google.com/calendar/appointments/schedules/AcZssZ1P3lnVUA-HnHlnVIwLcyxtvGs2WlLsbQXzDw92sYlEUILA90KSdqaieo5qmRkckf8xQgQ0ti8_?gv=true"
              className="sc-calendar-iframe"
              frameBorder="0"
              title="Book an Appointment"
            />
            <div className="sc-calendar-note">
              <small>
                Can't see the calendar?{" "}
                <a
                  href="https://calendar.google.com/calendar/appointments"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="sc-link"
                >
                  Open Google Calendar directly →
                </a>
              </small>
            </div>
          </div>
        </div>
      )}

      {/* Message Panel */}
      {activePanel === "message" && (
        <div className="sc-panel">
          <div className="sc-panel-header">
            <span>
              {" "}
              <MessageCircleMore size={18} /> Send us a Message
            </span>
            <button
              className="sc-close-btn"
              onClick={() => setActivePanel(null)}
            >
              ✕
            </button>
          </div>
          <form onSubmit={handleFormSubmit} className="sc-form">
            <div className="sc-form-grid">
              <div className="sc-form-group">
                <input
                  className="sc-input"
                  type="text"
                  placeholder="Your Name"
                  required
                />
              </div>
              <div className="sc-form-group">
                <input
                  className="sc-input"
                  type="email"
                  placeholder="Email Address"
                  required
                />
              </div>
              <div className="sc-form-group">
                <input className="sc-input" type="text" placeholder="Subject" />
              </div>
              <div className="sc-form-group">
                <input
                  className="sc-input"
                  type="tel"
                  placeholder="Phone Number"
                />
              </div>
            </div>
            <div className="sc-form-group">
              <textarea
                className="sc-input sc-textarea"
                placeholder="Project Details"
                rows="5"
                required
              />
            </div>
            <button type="submit" className="sc-submit-btn">
              Send Message →
            </button>
          </form>
        </div>
      )}
    </div>
  );
};

export default ServiceContact;
