import SEO from "../SEO";
import React, { useEffect, useRef, useState } from "react";
import {
  Lightbulb,
  Search,
  Code,
  Rocket,
  CheckCircle,
  Users,
  Target,
  Zap,
} from "lucide-react";
import "../../styles/HowWeWork.css";
import { Link } from "react-router-dom";

const HowWeWork = () => {
  const [hoveredStep, setHoveredStep] = useState(null);
  const [hoveredFeature, setHoveredFeature] = useState(null);

  const workSteps = [
    {
      id: 1,
      icon: <Search size={32} />,
      title: "Discovery & Research",
      description:
        "We deep dive into your business goals, target audience, and market landscape to create a solid foundation for your project.",
      duration: "1-2 weeks",
      color: "#2563eb",
    },
    {
      id: 2,
      icon: <Lightbulb size={32} />,
      title: "Strategy & Planning",
      description:
        "Our team crafts a comprehensive strategy and roadmap tailored to your unique requirements and business objectives.",
      duration: "1 week",
      color: "#2563eb",
    },
    {
      id: 3,
      icon: <Code size={32} />,
      title: "Design & Development",
      description:
        "We bring your vision to life with cutting-edge design and robust development, ensuring pixel-perfect execution.",
      duration: "4-8 weeks",
      color: "#2563eb",
    },
    {
      id: 4,
      icon: <CheckCircle size={32} />,
      title: "Testing & Quality Assurance",
      description:
        "Rigorous testing across devices and browsers ensures flawless performance and user experience before launch.",
      duration: "1-2 weeks",
      color: "#2563eb",
    },
    {
      id: 5,
      icon: <Rocket size={32} />,
      title: "Launch & Deployment",
      description:
        "Strategic launch with seamless deployment, ensuring your store goes live without a hitch and performs optimally.",
      duration: "3-5 days",
      color: "#2563eb",
    },
    {
      id: 6,
      icon: <Target size={32} />,
      title: "Support & Optimization",
      description:
        "Continuous monitoring, updates, and optimization to keep your store performing at peak levels and growing.",
      duration: "Ongoing",
      color: "#2563eb",
    },
  ];

  const features = [
    {
      icon: <Users size={40} />,
      title: "Dedicated Team",
      description:
        "A committed team of experts working exclusively on your project with full transparency.",
    },
    {
      icon: <Zap size={40} />,
      title: "Agile Methodology",
      description:
        "Flexible, iterative approach allowing quick adaptations and continuous improvement.",
    },
    {
      icon: <CheckCircle size={40} />,
      title: "Quality Assurance",
      description:
        "Multi-layer testing process ensuring bug-free, high-performance deliverables.",
    },
    {
      icon: <Target size={40} />,
      title: "Results-Driven",
      description:
        "Focus on measurable outcomes that directly impact your business growth and ROI.",
    },
  ];

  const heroSectionRef = useRef(null);
  const mouseFollowerRef = useRef(null);

  useEffect(() => {
    // ===== Blur Vanish Effect =====
    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          if (entry.target.id === "missionProgress") {
            setTimeout(() => {
              entry.target.classList.add("animate");
            }, 500);
          }
        }
      });
    }, observerOptions);

    const blurElements = document.querySelectorAll(
      ".blur-vanish, .blur-vanish-left, .blur-vanish-right, .blur-vanish-scale, .stagger-item, .blur-glow, .floating-blur, .text-blur-reveal"
    );
    blurElements.forEach((el) => observer.observe(el));

    const progressBar = document.getElementById("missionProgress");
    if (progressBar) observer.observe(progressBar);

    // ===== Hover Effects =====
    const hoverElements = document.querySelectorAll(".enhanced-hover");
    hoverElements.forEach((el) => {
      el.addEventListener("mouseenter", function () {
        this.style.transform = "translateY(-8px) scale(1.02)";
        this.style.boxShadow = "0 20px 40px rgba(92, 39, 254, 0.15)";
        this.style.filter = "drop-shadow(0 8px 16px rgba(0, 0, 0, 0.1))";
      });
      el.addEventListener("mouseleave", function () {
        this.style.transform = "";
        this.style.boxShadow = "";
        this.style.filter = "";
      });
    });

    // ===== Dynamic cursor =====
    const interactiveElements = document.querySelectorAll(
      ".btn-primary, .cta-button, .enhanced-hover"
    );
    interactiveElements.forEach((el) => {
      el.addEventListener("mouseenter", () => {
        document.body.style.cursor = "pointer";
      });
      el.addEventListener("mouseleave", () => {
        document.body.style.cursor = "default";
      });
    });

    // ===== Ripple Effect =====
    const buttons = document.querySelectorAll(".btn-primary, .cta-button");
    buttons.forEach((btn) => {
      btn.addEventListener("click", function (e) {
        const ripple = document.createElement("span");
        const rect = this.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height);
        const x = e.clientX - rect.left - size / 2;
        const y = e.clientY - rect.top - size / 2;

        ripple.style.cssText = `
            position: absolute;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.6);
            transform: scale(0);
            animation: ripple 0.6s linear;
            width: ${size}px;
            height: ${size}px;
            left: ${x}px;
            top: ${y}px;
            pointer-events: none;
          `;

        this.style.position = "relative";
        this.style.overflow = "hidden";
        this.appendChild(ripple);

        setTimeout(() => ripple.remove(), 600);
      });
    });

    // Inject Ripple CSS
    const style = document.createElement("style");
    style.textContent = `
        @keyframes ripple {
          to {
            transform: scale(4);
            opacity: 0;
          }
        }
      `;
    document.head.appendChild(style);

    // ===== Scroll Effects =====
    const onScroll = () => {
      const scrolled = window.pageYOffset;
      const header = document.getElementById("header");
      if (scrolled > 100) {
        header?.classList.add("scrolled");
      } else {
        header?.classList.remove("scrolled");
      }

      const heroImage = document.querySelector(".hero-image");
      if (heroImage) {
        heroImage.style.transform = `translateY(${scrolled * 0.3}px)`;
      }
    };

    window.addEventListener("scroll", onScroll);

    // ===== Smooth Anchor Scroll =====
    const anchors = document.querySelectorAll('a[href^="#"]');
    anchors.forEach((a) => {
      a.addEventListener("click", function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute("href"));
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    // ===== Floating Avatars =====
    const avatars = document.querySelectorAll(".team-avatar");
    avatars.forEach((avatar, i) => {
      avatar.style.animation = "float 3s ease-in-out infinite";
      avatar.style.animationDelay = `${i * 0.5}s`;
    });

    const floatingStyle = document.createElement("style");
    floatingStyle.textContent = `
        @keyframes float {
          0%, 100% { transform: translateY(0px); }
          50% { transform: translateY(-10px); }
        }
      `;
    document.head.appendChild(floatingStyle);

    // ===== Mousemove 3D Cards =====
    const cards = document.querySelectorAll(
      ".client-card, .team-card, .vision-item, .why-card"
    );
    document.addEventListener("mousemove", (e) => {
      cards.forEach((card) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
          const centerX = rect.width / 2;
          const centerY = rect.height / 2;
          const rotateX = (y - centerY) / 10;
          const rotateY = (centerX - x) / 10;
          card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.02)`;
        } else {
          card.style.transform = "";
        }
      });
    });

    // ===== Cleanup =====
    return () => {
      window.removeEventListener("scroll", onScroll);
      observer.disconnect();
    };
  }, []);

  // Mouse follower effect
  useEffect(() => {
    const heroSection = heroSectionRef.current;
    const mouseFollower = mouseFollowerRef.current;

    if (!heroSection || !mouseFollower) return;

    const handleMouseMove = (e) => {
      const rect = heroSection.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      mouseFollower.style.left = x + "px";
      mouseFollower.style.top = y + "px";
    };

    heroSection.addEventListener("mousemove", handleMouseMove);

    return () => {
      heroSection.removeEventListener("mousemove", handleMouseMove);
    };
  }, []);

  return (
    <div className="TCL-Work_Page">
      {/* header */}
      <div className="case-study-page">
        <section
          className="case-hero-section how-work-header"
          ref={heroSectionRef}
        >
          {/* Mouse-following glow effect */}
          <div className="case-mouse-follower" ref={mouseFollowerRef}></div>

          {/* Animated background elements */}
          <div className="case-bg-overlay">
            <div className="case-bg-circle-1"></div>
            <div className="case-bg-circle-2"></div>
          </div>

          {/* Dot pattern overlay */}
          <div className="case-dot-pattern"></div>
          {/* Content */}
          <div className="case-hero-content">
            {/* Badge */}
            <div className="case-hero-badge">
              <svg
                className="case-badge-icon"
                fill="currentColor"
                viewBox="0 0 20 20"
              >
                <path
                  fillRule="evenodd"
                  d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 2.812c.051.643.304 1.254.723 1.745a3.066 3.066 0 010 3.976 3.066 3.066 0 00-.723 1.745 3.066 3.066 0 01-2.812 2.812 3.066 3.066 0 00-1.745.723 3.066 3.066 0 01-3.976 0 3.066 3.066 0 00-1.745-.723 3.066 3.066 0 01-2.812-2.812 3.066 3.066 0 00-.723-1.745 3.066 3.066 0 010-3.976 3.066 3.066 0 00.723-1.745 3.066 3.066 0 012.812-2.812zm7.44 5.252a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z"
                  clipRule="evenodd"
                />
              </svg>
              <span className="case-badge-text">How We Work</span>
            </div>

            {/* Main heading */}
            <h1 className="case-hero-title">
              Our Proven Path to
              {/* <br /> */}
              <span className="case-gradient-text"> Real Growth</span>
            </h1>

            {/* Description */}
            <p className="case-hero-description how-we-description">
              We transform complex challenges into streamlined, high-converting
              solutions. Discover the six stages of our collaborative process.
            </p>

            <div className="cta-buttons">
              {/* <Link to="" className="btn-primary blur-vanish-scale visible">
                View Success Stories
              </Link> */}
              <Link
                to=""
                className="btn-secondary blur-vanish-scale visible case-btn-secondary"
              >
                Start Your Project
              </Link>
            </div>
          </div>
        </section>
      </div>

      <div className="hww-main-container">
        {/* Introduction Section */}
        <div className="hww-intro-section">
          <h1 className="hww-intro-title">How We Work</h1>
          <p className="hww-intro-subtitle">
            Our proven process combines strategy, creativity, and technology to
            deliver exceptional results. From concept to launch, we're with you
            every step of the way.
          </p>
        </div>

        {/* Process Steps Section */}
        <div className="hww-steps-section">
          <div className="hww-steps-container">
            <div className="hww-section-header">
              <h2 className="hww-section-title">Our Process</h2>
              <p className="hww-section-description">
                A transparent, collaborative approach that ensures your
                project's success at every stage
              </p>
            </div>

            <div className="hww-timeline-container">
              <div className="hww-timeline-line"></div>

              {workSteps.map((step, index) => (
                <div
                  key={step.id}
                  className="hww-step-wrapper"
                  onMouseEnter={() => setHoveredStep(step.id)}
                  onMouseLeave={() => setHoveredStep(null)}
                >
                  <div className="hww-step-card">
                    <div className="hww-step-number">{step.id}</div>
                    <div className="hww-step-header">
                      <div
                        className="hww-step-icon-small"
                        style={{
                          background: `#2563eb`,
                        }}
                      >
                        {step.icon}
                      </div>
                      <h3 className="hww-step-title">{step.title}</h3>
                    </div>
                    <p className="hww-step-description">{step.description}</p>
                    <div style={{ marginTop: "20px" }}>
                      <span className="hww-step-duration">
                        ⏱ {step.duration}
                      </span>
                    </div>
                  </div>
                  <div
                    className="hww-step-icon-wrapper"
                    style={{
                      background:
                        hoveredStep === step.id ? step.color : "white",
                      color: hoveredStep === step.id ? "white" : step.color,
                    }}
                  >
                    {step.icon}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Features Section */}
        <div className="hww-features-section">
          <div className="hww-features-wrapper">
            <div className="hww-section-header">
              <h2 className="hww-section-title2">Why Our Process Works</h2>
              <p className="hww-section-description2">
                Built on best practices and refined through hundreds of
                successful projects
              </p>
            </div>

            <div className="hww-features-grid">
              {features.map((feature, index) => (
                <div
                  key={index}
                  className="hww-feature-card"
                  onMouseEnter={() => setHoveredFeature(index)}
                  onMouseLeave={() => setHoveredFeature(null)}
                >
                  <div className="hww-feature-icon">{feature.icon}</div>
                  <h3 className="hww-feature-title">{feature.title}</h3>
                  <p className="hww-feature-description">
                    {feature.description}
                  </p>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Call to Action Section */}
        <div className="hww-cta-section">
          <h2 className="hww-cta-title">Ready to Start Your Project?</h2>
          <p className="hww-cta-description">
            Let's discuss how we can help bring your vision to life with our
            proven process and expert team.
          </p>
          <div className="cta-buttons">
            {/* <Link to="" className="btn-primary blur-vanish-scale visible">
                View Success Stories
              </Link> */}
            <Link
              to="/"
              className="btn-primary blur-vanish-scale visible case-btn-secondary"
            >
              Start Your Project
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

export default HowWeWork;
