function SocialProofToast() {
  const [visible, setVisible] = useState(false);
  const [current, setCurrent] = useState(0);

const notifications = [
  {
    icon: <Calendar size={18} color="#6B8356" />,
    text: "Sarah M. just booked a strategy call",
    time: "2 min ago",
  },
  {
    icon: <CheckCircle size={18} color="#4A6438" />,
    text: "54 Thrones project delivered — +42% CVR",
    time: "3 hours ago",
  },
  {
    icon: <Search size={18} color="#6B8356" />,
    text: "New store audit requested from Toronto",
    time: "8 min ago",
  },
  {
    icon: <Rocket size={18} color="#4A6438" />,
    text: "Bird&Be subscription revenue hit 2× target",
    time: "1 day ago",
  },
  {
    icon: <Calendar size={18} color="#6B8356" />,
    text: "David C. just booked a strategy call",
    time: "15 min ago",
  },
  {
    icon: <BarChart2 size={18} color="#4A6438" />,
    text: "Free store analysis — 847 scans this month",
    time: "Just now",
  },
];

  useEffect(() => {
    const showNext = () => {
      setVisible(true);
      setTimeout(() => setVisible(false), 4000);
      setTimeout(() => setCurrent((c) => (c + 1) % notifications.length), 4800);
    };
    const initial = setTimeout(showNext, 8000);
    const interval = setInterval(showNext, 18000);
    return () => {
      clearTimeout(initial);
      clearInterval(interval);
    };
  }, []);

  const n = notifications[current];
  return (
    <div
      style={{
        position: "fixed",
        bottom: 80,
        left: 24,
        zIndex: 1400,
        background: "#fff",
        borderRadius: 14,
        padding: "14px 18px",
        boxShadow: "0 8px 30px rgba(0,0,0,.12)",
        border: "1px solid rgba(0,0,0,.06)",
        display: "flex",
        alignItems: "center",
        gap: 12,
        maxWidth: 320,
        opacity: visible ? 1 : 0,
        transform: visible ? "translateX(0)" : "translateX(-120%)",
        transition: "all .5s cubic-bezier(.23,1,.32,1)",
        pointerEvents: visible ? "auto" : "none",
      }}
    >
      <span style={{ fontSize: 24, flexShrink: 0 }}>{n.icon}</span>
      <div>
        <div
          style={{
            fontSize: 13,
            fontWeight: 600,
            color: "#3D4A35",
            lineHeight: 1.4,
          }}
        >
          {n.text}
        </div>
        <div style={{ fontSize: 11, color: "#B5AFA8", marginTop: 2 }}>
          {n.time}
        </div>
      </div>
    </div>
  );
}

