/* ─── Cookie Consent ─── */
function CookieConsent() {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const accepted =
      window.localStorage && window.localStorage.getItem("cookie_consent");
    if (!accepted) setTimeout(() => setVisible(true), 2000);
  }, []);
  const accept = () => {
    if (window.localStorage)
      window.localStorage.setItem("cookie_consent", "true");
    setVisible(false);
    // Initialize Google Analytics after consent
    if (window.gtag) {
      window.gtag("consent", "update", { analytics_storage: "granted" });
    }
  };
  if (!visible) return null;
  return (
    <div
      className="sp-fixed-bottom-bar"
      style={{
        position: "fixed",
        bottom: 0,
        left: 0,
        right: 0,
        zIndex: 2500,
        background: "#fff",
        boxShadow: "0 -4px 20px rgba(0,0,0,.1)",
        padding: "16px 28px",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 16,
        flexWrap: "wrap",
      }}
    >
      <p
        style={{
          fontSize: 13,
          color: "#5E5A54",
          margin: 0,
          flex: 1,
          minWidth: 200,
        }}
      >
        🍪 We use cookies to improve your experience and analyze site traffic.
        By continuing, you agree to our use of cookies.
      </p>
      <div style={{ display: "flex", gap: 8 }}>
        <button
          onClick={accept}
          style={{
            padding: "8px 24px",
            borderRadius: 8,
            border: "none",
            background: "#4A6438",
            color: "#fff",
            fontSize: 13,
            fontWeight: 600,
            cursor: "pointer",
          }}
        >
          Accept
        </button>
        <button
          onClick={() => setVisible(false)}
          style={{
            padding: "8px 16px",
            borderRadius: 8,
            border: "1px solid #D5D0C8",
            background: "transparent",
            color: "#8A857E",
            fontSize: 13,
            cursor: "pointer",
          }}
        >
          Decline
        </button>
      </div>
    </div>
  );
}

