// --- Components ---

const Header = () => (
  <header className="header-bar">
    <div className="careers-container header-content">
      <h1 className="logo-text">TechTCL</h1>
      <button className="login-button">Client Login</button>
    </div>
  </header>
);

const HeroSection = () => (
  <section className="careers-container hero-section">
    <div className="hero-text-content">
      <h2 className="tagline">Join Our Team</h2>
      <h1 className="hero-title">
        Innovate, Create, Thrive.{" "}
        <span className="highlight-text">Join the TechTCL Team.</span>
      </h1>
      <p className="hero-description">
        We're a dynamic digital agency building the future of web experiences.
        We hire people who are passionate about their craft and driven to make a
        real impact on our clients and the industry.
      </p>
      <a href="#openings" className="btn-primary blur-vanish-scale visible">
        See Current Openings <Briefcase className="icon ml-10" />
      </a>
    </div>
    <div className="hero-image-careers-container">
      <img
        className="hero-image"
        src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/project.webp?v=1772168476"
        alt="TechTCL team members collaborating on a project."
      />
      <div className="hero-image-overlay"></div>
    </div>
  </section>
);

const SectionTitle = ({ title, subtitle, id }) => (
  <div id={id} className="section-title-careers-container">
    <h2 className="tagline Current-Openings">{subtitle}</h2>
    <h3 className="section-main-title global-body-heading-fonts">{title}</h3>
  </div>
);

const BenefitsSection = () => (
  <section className="section section-benefits">
    <div className="careers-container">
      <SectionTitle title="The Perks of Joining TechTCL" subtitle="Benefits" />

      <div className="benefits-grid">
        {benefitsData.map((benefit, index) => (
          <div key={index} className="benefit-card">
            <benefit.icon className="benefit-icon" />
            <h4 className="card-title">{benefit.title}</h4>
            <p className="card-description">{benefit.description}</p>
            <div className="shopify-problem-hover-indicator career-hover-card-indicator"></div>
          </div>
        ))}
      </div>

      <div className="content-image-layout reverse-on-desktop">
        <div className="image-wrapper">
          <img
            className="content-image"
            src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/Remote-Workplace.webp?v=1772168639"
            alt="Person happily working remotely on a laptop"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src =
                "https://cdn.shopify.com/s/files/1/0644/4086/0781/files/Remote-Workplace.webp?v=1772168639";
            }}
          />
        </div>
        <div className="text-content">
          <h4 className="content-title">A Culture Focused on You</h4>
          <p className="content-paragraph">
            We believe that a well-supported and motivated team member is the
            key to delivering exceptional client work. Our benefits package is
            thoughtfully designed to empower your life, both inside and outside
            of work.
          </p>
        </div>
      </div>
    </div>
  </section>
);

const ValuesSection = () => (
  <section className="section">
    <div className="careers-container">
      <SectionTitle
        title="The Principles That Guide Our Work"
        subtitle="Our Core Values"
      />

      <div className="values-grid">
        {valuesData.map((value, index) => (
          <div key={index} className="value-item">
            <value.icon className="value-icon" />
            <h4 className="card-title">{value.title}</h4>
            <p className="card-description small">{value.description}</p>
          </div>
        ))}
      </div>

      <div className="content-image-layout">
        <div className="text-content">
          <h4 className="content-title">Making an Impact Together</h4>
          <p className="content-paragraph">
            Our values aren't just posters on a wall; they define how we
            interact with each other and our clients every day. They are the
            foundation of TechTCL's success and the driving force behind our
            innovation.
          </p>
        </div>
        <div className="image-wrapper">
          <img
            className="content-image"
            src="https://placehold.co/800x500/374151/ffffff?text=Team+Collaborating+Virtually"
            alt="Team members collaborating virtually on a video call"
            onError={(e) => {
              e.target.onerror = null;
              e.target.src =
                "https://placehold.co/800x500/374151/ffffff?text=Team+Collaborating+Virtually";
            }}
          />
        </div>
      </div>
    </div>
  </section>
);

const JobOpeningCard = ({ role, department, location }) => (
  <div className="job-card">
    <h4 className="job-role">{role}</h4>
    <p className="job-department">{department}</p>
    <div className="job-location">
      <MapPin className="icon-small" />
      <span>{location}</span>
    </div>
    <div className="job-details-link">
      <button className="details-button">View Details &rarr;</button>
    </div>
  </div>
);

