const OpeningsSection = () => (
  <section className="section section-openings">
    <div className="careers-container">
      <SectionTitle
        title="Find Your Next Career Move"
        subtitle="Current Openings"
        id="openings"
      />

      <div className="no-openings">
        <span className="no-openings-icon">
          <img src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/tools-and-utensils.png?v=1772260163" />
        </span>
        <h3 className="no-openings-heading">We're Building Something Big</h3>
        <p className="no-openings-text">
          No open roles right now — but great things are brewing. <br />
          Drop your resume and be the first we call when the doors open.
        </p>
      </div>

      <div className="application-prompt">
        <p className="prompt-text">
          Don't see your perfect fit? Send us your resume anyway!
        </p>
        <button className="btn-outline">Submit General Application</button>
      </div>
    </div>
  </section>
);

const MapPin = ({ className }) => (
  <svg
    className={className}
    xmlns="http://www.w3.org/2000/svg"
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    strokeLinecap="round"
    strokeLinejoin="round"
  >
    <path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" />
    <circle cx="12" cy="10" r="3" />
  </svg>
);

const FAQItem = ({ question, answer }) => {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="faq-item-careers-container">
      <button className="faq-button" onClick={() => setIsOpen(!isOpen)}>
        <span className="faq-question">{question}</span>
        <ChevronDown className={`faq-icon ${isOpen ? "rotate" : ""}`} />
      </button>
      <div className={`faq-answer-content ${isOpen ? "open" : ""}`}>
        <p className="faq-answer-text">{answer}</p>
      </div>
    </div>
  );
};

const FAQSection = () => (
  <section className="section">
    <div className="careers-container">
      <SectionTitle title="Quick Answers to Common Questions" subtitle="FAQs" />

      <div className="faq-list">
        {faqData.map((faq, index) => (
          <FAQItem key={index} question={faq.question} answer={faq.answer} />
        ))}
      </div>
    </div>
  </section>
);

const Footer = () => (
  <footer className="footer-bar">
    <div className="careers-container footer-content">
      <h3 className="footer-title">TechTCL</h3>
      <p className="footer-copyright">
        &copy; {new Date().getFullYear()} TechTCL. All rights reserved. | Grow
        with us.
      </p>
    </div>
  </footer>
);

// --- Main App Component ---

const App = () => {
  return (
    <div className="app-careers-container">
      {/* <Header /> */}
      <main>
        <HeroSection />
        <BenefitsSection />
        {/* <ValuesSection /> */}
        <OpeningsSection />
        <FAQSection />
      </main>
      {/* <Footer /> */}
    </div>
  );
};

export default App;
