import { useEffect, useRef } from "react";
import icon_planning from "../assets/planning.svg";
import icon_development from "../assets/development.svg";
import icon_testing from "../assets/testing.svg";
import icon_launch from "../assets/launch.svg";

export default function Approach() {
  const sectionRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const lines = entry.target.querySelectorAll(".line-segment");
            const steps = entry.target.querySelectorAll(".step");

            lines.forEach((line) => line.classList.add("animate"));
            steps.forEach((step) => step.classList.add("animate"));
          }
        });
      },
      { threshold: 0.3 },
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => {
      if (sectionRef.current) {
        observer.unobserve(sectionRef.current);
      }
    };
  }, []);

  return (
    <section className="ourapproch-section">
      <div className="container">
        <div className="title_wrapper">
          <div className="sort_title">
            <div class="tech-elementva8f4">
              <div class="tech-elementwebqt">How Techtcl works</div>
            </div>
          </div>
          <div className="main_title">
            <h2 className="global-body-heading-fonts">
              How Techtcl Brings Your Vision to Life
            </h2>
          </div>
        </div>

        <div className="approch_element_wrapper">
          {/* 👇 Attach ref here */}
          <div className="steps-container" ref={sectionRef}>
            <div className="line-container">
              <div className="line-segment">
                <div className="line-fill"></div>
              </div>
              <div className="line-segment">
                <div className="line-fill"></div>
              </div>
              <div className="line-segment">
                <div className="line-fill"></div>
              </div>
            </div>

            <div className="step">
              <div className="step-icon">
                <img loading="lazy" src={icon_planning} alt="Icon Planning" />
              </div>
              <h3 className="step-title">Project Planning</h3>
              <p className="step-description">
                We analyze your needs and create a detailed roadmap for success
              </p>
            </div>

            <div className="step">
              <div className="step-icon">
                <img
                  loading="lazy"
                  src={icon_development}
                  alt="Icon Development"
                />
              </div>
              <h3 className="step-title">Development</h3>
              <p className="step-description">
                Our expert team builds your solution using best practices and
                modern technology
              </p>
            </div>

            <div className="step">
              <div className="step-icon">
                <img loading="lazy" src={icon_testing} alt="Icon Testing" />
              </div>
              <h3 className="step-title">Testing</h3>
              <p className="step-description">
                Rigorous quality assurance ensures everything works flawlessly
              </p>
            </div>

            <div className="step">
              <div className="step-icon">
                <img loading="lazy" src={icon_launch} alt="Icon Launch" />
              </div>
              <h3 className="step-title">Launch + Support</h3>
              <p className="step-description">
                We deploy your project and provide ongoing maintenance and
                support
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
