import React, { useEffect } from "react";
import "../../styles/CaseStoryDetails.css";
import CustomerReviews from "../CustomerReviews";
import Cta from "../Cta";
import { FaShopify } from "react-icons/fa6";
import { MdLocationPin } from "react-icons/md";
import { Shirt } from "lucide-react";

const FirstCaseStory = () => {
  useEffect(() => {
    // ===== Blur Vanish Effect =====
    const observerOptions = {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px",
    };

    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          if (entry.target.id === "missionProgress") {
            setTimeout(() => {
              entry.target.classList.add("animate");
            }, 500);
          }
        }
      });
    }, observerOptions);

    const blurElements = document.querySelectorAll(
      ".blur-vanish, .blur-vanish-left, .blur-vanish-right, .blur-vanish-scale, .stagger-item, .blur-glow, .floating-blur, .text-blur-reveal",
    );
    blurElements.forEach((el) => observer.observe(el));

    const progressBar = document.getElementById("missionProgress");
    if (progressBar) observer.observe(progressBar);

    // ===== Hover Effects =====
    const hoverElements = document.querySelectorAll(".enhanced-hover");
    hoverElements.forEach((el) => {
      el.addEventListener("mouseenter", function () {
        this.style.transform = "translateY(-8px) scale(1.02)";
        this.style.boxShadow = "0 20px 40px rgba(92, 39, 254, 0.15)";
        this.style.filter = "drop-shadow(0 8px 16px rgba(0, 0, 0, 0.1))";
      });
      el.addEventListener("mouseleave", function () {
        this.style.transform = "";
        this.style.boxShadow = "";
        this.style.filter = "";
      });
    });

    // ===== Dynamic Cursor =====
    const interactiveElements = document.querySelectorAll(
      ".btn-primary, .cta-button, .enhanced-hover",
    );
    interactiveElements.forEach((el) => {
      el.addEventListener("mouseenter", () => {
        document.body.style.cursor = "pointer";
      });
      el.addEventListener("mouseleave", () => {
        document.body.style.cursor = "default";
      });
    });

    // ===== Ripple Effect =====
    const buttons = document.querySelectorAll(".btn-primary, .cta-button");
    buttons.forEach((btn) => {
      btn.addEventListener("click", function (e) {
        const ripple = document.createElement("span");
        const rect = this.getBoundingClientRect();
        const size = Math.max(rect.width, rect.height);
        const x = e.clientX - rect.left - size / 2;
        const y = e.clientY - rect.top - size / 2;

        ripple.style.cssText = `
          position: absolute;
          border-radius: 50%;
          background: rgba(255, 255, 255, 0.6);
          transform: scale(0);
          animation: ripple 0.6s linear;
          width: ${size}px;
          height: ${size}px;
          left: ${x}px;
          top: ${y}px;
          pointer-events: none;
        `;

        this.style.position = "relative";
        this.style.overflow = "hidden";
        this.appendChild(ripple);
        setTimeout(() => ripple.remove(), 600);
      });
    });

    const style = document.createElement("style");
    style.textContent = `
      @keyframes ripple {
        to { transform: scale(4); opacity: 0; }
      }
    `;
    document.head.appendChild(style);

    // ===== Scroll Effects =====
    const onScroll = () => {
      const scrolled = window.pageYOffset;
      const header = document.getElementById("header");
      if (scrolled > 100) {
        header?.classList.add("scrolled");
      } else {
        header?.classList.remove("scrolled");
      }
      const heroImage = document.querySelector(".hero-image");
      if (heroImage) {
        heroImage.style.transform = `translateY(${scrolled * 0.3}px)`;
      }
    };
    window.addEventListener("scroll", onScroll);

    // ===== Smooth Anchor Scroll =====
    const anchors = document.querySelectorAll('a[href^="#"]');
    anchors.forEach((a) => {
      a.addEventListener("click", function (e) {
        e.preventDefault();
        const target = document.querySelector(this.getAttribute("href"));
        target?.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    // ===== Floating Avatars =====
    const avatars = document.querySelectorAll(".team-avatar");
    avatars.forEach((avatar, i) => {
      avatar.style.animation = "float 3s ease-in-out infinite";
      avatar.style.animationDelay = `${i * 0.5}s`;
    });

    const floatingStyle = document.createElement("style");
    floatingStyle.textContent = `
      @keyframes float {
        0%, 100% { transform: translateY(0px); }
        50% { transform: translateY(-10px); }
      }
    `;
    document.head.appendChild(floatingStyle);

    // ===== Mousemove 3D Cards =====
    const cards = document.querySelectorAll(
      ".client-card, .team-card, .vision-item, .why-card",
    );
    document.addEventListener("mousemove", (e) => {
      cards.forEach((card) => {
        const rect = card.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        if (x >= 0 && x <= rect.width && y >= 0 && y <= rect.height) {
          const centerX = rect.width / 2;
          const centerY = rect.height / 2;
          const rotateX = (y - centerY) / 10;
          const rotateY = (centerX - x) / 10;
          card.style.transform = `perspective(1000px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) scale(1.02)`;
        } else {
          card.style.transform = "";
        }
      });
    });

    // ===== Cleanup =====
    return () => {
      window.removeEventListener("scroll", onScroll);
      observer.disconnect();
    };
  }, []);

  return (
    <>
      <div className="case-story-container">
        {/* ── Hero Banner ── */}
        <section className="case-details-hero-banner">
          <div className="case-details-hero-pattern"></div>
          <div className="case-details-container">
            <div className="case-details-hero-content">
              <div className="case-study-badge">
                <i className="fas fa-star"></i>
                SUCCESS STORY
              </div>
              <h1 className="melissa-hero-title">
                Their Fashion Store Was Full of Shoppers, But Empty of Sales
              </h1>
              <p>
                A modern apparel brand was getting clicks but almost no sales.
                Visitors browsed and left. The products were strong, but the
                store experience wasn’t. We fixed it in 13 days—without spending
                more on traffic.
              </p>
              <div className="case-details-hero-stats">
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">289%</span>
                  <span className="case-details-stat-label">REVENUE SURGE</span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">3.8%</span>
                  <span className="case-details-stat-label">
                    CONVERSION RATE
                  </span>
                </div>
                <div className="case-details-stat-item">
                  <span className="case-details-stat-number">54%</span>
                  <span className="case-details-stat-label">
                    LESS CART ABANDONMENT
                  </span>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* ── Client Overview Card ── */}
        <div className="case-details-container">
          <div className="case-details-client-card">
            <div className="case-details-client-header">
              <div className="case-details-client-logo">
                <div className="case-details-client-logo">
                  <img
                    src="https://cdn.shopify.com/s/files/1/0644/4086/0781/files/Lumine_Label.webp?v=1771989909"
                    alt="Lumene Label Logo"
                  />
                </div>
              </div>
              <div className="case-details-client-info">
                <h2>Lumene Label</h2>
                <div className="case-details-client-meta">
                  <div className="case-details-meta-item">
                    <Shirt size={16} />
                    Contemporary Apparel Brand
                  </div>
                  <div className="case-details-meta-item">
                    <FaShopify />
                    Shopify Platform
                  </div>
                  <div className="case-details-meta-item">
                    <MdLocationPin />
                    United States
                  </div>
                </div>
              </div>
            </div>
            <div className="quick-facts">
              <div className="fact-box">
                <div className="label">Project Duration</div>
                <div className="value">13 Days</div>
              </div>
              <div className="fact-box">
                <div className="label">Primary Issue</div>
                <div className="value">The Silent Conversion Killer</div>
              </div>
              <div className="fact-box">
                <div className="label">Industry</div>
                <div className="value">Apparel / DTC Fashion</div>
              </div>
              <div className="fact-box">
                <div className="label">SERVICES PROVIDED</div>
                <div className="value">Full CRO Audit &amp; Rebuild</div>
              </div>
            </div>
          </div>
        </div>

        {/* ── Content Wrapper ── */}
        <div className="case-details-content-wrapper">
          {/* ── Challenge Section ── */}
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-exclamation-triangle"></i>
              </div>
              <h2>The Breaking Point</h2>
            </div>
            <p className="section-intro">
              Lumene Label was doing everything right on the marketing side.
              Their Instagram ads were generating thousands of clicks every
              week, their email list was growing, and their products had a
              genuine following. But their conversion rate sat at a devastating
              1.1%, meaning 99 out of every 100 visitors left without buying a
              single item. At an average order value of $92, that's over $2,500
              in lost revenue every single day. The real problem wasn't the
              product, it was the store. Visitors landed on beautifully shot
              product pages and then got stuck. Sizing info was buried, checkout
              felt uncertain, social proof was invisible, and the mobile
              experience was a frustrating mess. Every friction point was a
              reason to leave instead of buy. And no amount of ad budget would
              fix that.
            </p>

            <div className="challenge-grid">
              <div className="challenge-visual">
                <div className="speed-indicator">
                  <div className="speed-circle">
                    <div className="speed-inner">
                      <span className="speed-score">1.1%</span>
                      <span className="speed-label">CVR</span>
                    </div>
                  </div>
                </div>
                <div className="problem-tag">
                  <i className="fas fa-times-circle"></i> Critically Low
                </div>
              </div>

              <div className="challenge-list">
                <div className="challenge-item">
                  <i className="fas fa-ruler"></i>
                  <div className="text">
                    <strong>No Size Guidance on Product Pages</strong>
                    <p>
                      Shoppers couldn't find a size guide easily, the #1 reason
                      fashion customers abandon without buying
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-shopping-cart"></i>
                  <div className="text">
                    <strong>76% Cart Abandonment Rate</strong>
                    <p>
                      Nearly 3 in 4 customers who added items to cart never
                      completed their purchase, checkout friction was destroying
                      intent
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-shield-alt"></i>
                  <div className="text">
                    <strong>Zero Visible Trust Signals</strong>
                    <p>
                      No return policy badge, no secure checkout indicator, no
                      reviews above the fold, first-time buyers had no reason to
                      trust
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-mobile-alt"></i>
                  <div className="text">
                    <strong>Broken Mobile Shopping Experience</strong>
                    <p>
                      78% of traffic came from mobile, yet product images were
                      unswipeable and the add-to-cart button was partially
                      hidden
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-star-half-alt"></i>
                  <div className="text">
                    <strong>Reviews Hidden Below the Fold</strong>
                    <p>
                      Over 300 genuine five-star reviews were buried so deep
                      that less than 12% of visitors ever saw them
                    </p>
                  </div>
                </div>
                <div className="challenge-item">
                  <i className="fas fa-random"></i>
                  <div className="text">
                    <strong>No Upsell or Cross-Sell Strategy</strong>
                    <p>
                      Customers buying one item had no visible path to complete
                      the look, leaving significant AOV gains untouched
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </section>
        </div>

        <Cta />

        {/* ── Strategy Section ── */}
        <div className="case-details-content-wrapper2">
          <section className="case-details-section">
            <div className="case-details-section-header">
              <div className="section-icon">
                <i className="fas fa-lightbulb"></i>
              </div>
              <h2>Our Strategy</h2>
            </div>
            <div className="strategy-intro">
              <p className="section-intro">
                We didn't touch the ads. We fixed the store. Our team ran a full
                48-hour CRO diagnostic, analyzing session recordings, heatmaps,
                and funnel drop-off data to identify every point where Lumene
                Label was losing buyers it had already paid to attract. Then we
                executed a precise, 13-day conversion rebuild designed
                specifically for fashion DTC: fixing the friction, building the
                trust, and engineering a checkout path that felt as effortless
                as shopping in-store.
              </p>
            </div>

            <div className="strategy-cards">
              <div className="strategy-card">
                <div className="card-number">01</div>
                <h3>
                  <i className="fas fa-search"></i> Full CRO Audit &amp;
                  Customer Journey Mapping
                </h3>
                <ul>
                  <li>
                    Reviewed 30 days of session recordings to pinpoint the exact
                    moments visitors decided to leave
                  </li>
                  <li>
                    Ran scroll-depth and click heatmap analysis across homepage,
                    collection pages, and top-selling product pages
                  </li>
                  <li>
                    Identified 16 conversion blockers ranked by revenue impact,
                    creating a clear fix-first priority list
                  </li>
                  <li>
                    Mapped the complete mobile purchase journey end-to-end,
                    click to confirmation across 8 device types
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">02</div>
                <h3>
                  <i className="fas fa-tshirt"></i> Fashion-First Product Page
                  Rebuild
                </h3>
                <ul>
                  <li>
                    Restructured the above-the-fold layout to lead with the
                    product name, star rating, price, and a dominant CTA. All
                    visible without a single scroll
                  </li>
                  <li>
                    Built an integrated size guide modal that opens inline, no
                    page leave, no hesitation, no abandoned carts over fit
                    uncertainty
                  </li>
                  <li>
                    Introduced a color and variant selector with real product
                    thumbnail swatches so shoppers see exactly what they're
                    choosing
                  </li>
                  <li>
                    Added a sticky add-to-cart bar that persists as users scroll
                    through product details and reviews
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">03</div>
                <h3>
                  <i className="fas fa-shield-alt"></i> Trust Layer Installation
                </h3>
                <ul>
                  <li>
                    Designed a trust bar placed directly under the hero with
                    free returns badge, secure checkout lock, and delivery
                    estimate
                  </li>
                  <li>
                    Moved the top 6 customer reviews with photos, to directly
                    beneath the product title, above the description
                  </li>
                  <li>
                    Added real-wear customer photo gallery to every product
                    page, showing the clothes on real body types
                  </li>
                  <li>
                    Built a visible return &amp; exchange policy section with a
                    single click to initiate, removing the last reason to
                    hesitate
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">04</div>
                <h3>
                  <i className="fas fa-shopping-cart"></i> Checkout Friction
                  Elimination
                </h3>
                <ul>
                  <li>
                    Consolidated a 5-step checkout into 3 screens by combining
                    address and delivery preference fields
                  </li>
                  <li>
                    Surfaced Shop Pay, Apple Pay, and Google Pay as the primary
                    checkout options above the standard form, reducing checkout
                    time by 64%
                  </li>
                  <li>
                    Added a persistent mini order summary with product images in
                    the cart drawer sidebar, buyers never forgot what they were
                    buying
                  </li>
                  <li>
                    Fixed all mobile checkout follow breaks, buttons, input
                    fields, and keyboard interactions rebuilt from scratch for
                    thumb-first use
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">05</div>
                <h3>
                  <i className="fas fa-layer-group"></i> "Complete the Look"
                  Upsell System
                </h3>
                <ul>
                  <li>
                    Built a "Complete the Look" cross-sell module on every
                    product page pairing tops with bottoms, shoes, and
                    accessories from the same collection
                  </li>
                  <li>
                    Added an in-cart upsell offering a discount on a second item
                    once the free shipping threshold was reached
                  </li>
                  <li>
                    Created a post-purchase one-click upsell for a matching
                    accessory, zero re-entry of payment details required
                  </li>
                  <li>
                    Implemented a "customers also bought" row on the cart page
                    with single-tap add to cart functionality
                  </li>
                </ul>
              </div>

              <div className="strategy-card">
                <div className="card-number">06</div>
                <h3>
                  <i className="fas fa-mobile-alt"></i> Mobile Experience
                  Overhaul
                </h3>
                <ul>
                  <li>
                    Rebuilt the product image gallery as a full-width swipeable
                    carousel with zoom-on-tap, the way fashion shoppers actually
                    browse
                  </li>
                  <li>
                    Redesigned all CTAs with thumb-zone sizing so the
                    add-to-cart button is always reachable with one hand
                  </li>
                  <li>
                    Optimized font sizes, line heights, and touch targets across
                    all key pages for 375px–428px viewports
                  </li>
                  <li>
                    QA tested across 14 device and browser combinations before
                    launch, zero rendering issues at go-live
                  </li>
                </ul>
              </div>
            </div>
          </section>
        </div>

        {/* ── Results Showcase ── */}
        <section className="results-showcase">
          <div className="case-details-result-content-wrapper">
            <div className="results-header">
              <h2>
                <i className="fas fa-trophy"></i> The Results
              </h2>
              <p className="results-description-intro">
                In just 13 days, Lumene Label's store transformed from a
                high-traffic, low-revenue liability into their single most
                profitable growth channel. Same ad budget. Same products. A
                completely different outcome. Their founder's words said it
                best: "I wish we'd done this before our last two ad campaigns.
                We were paying for traffic that our store was throwing away."
              </p>
            </div>

            <div className="metrics-grid">
              <div className="metric-card">
                <div className="case-details-metric-label">Conversion Rate</div>
                <div className="metric-comparison">
                  <span className="metric-before">1.1%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">3.8%</span>
                </div>
                <div className="improvement-badge">+245% Increase</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Cart Abandonment
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">76%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">35%</span>
                </div>
                <div className="improvement-badge">54% Reduction</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">
                  Avg. Order Value
                </div>
                <div className="metric-comparison">
                  <span className="metric-before">$92</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">$139</span>
                </div>
                <div className="improvement-badge">+51% Higher AOV</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Monthly Revenue</div>
                <div className="metric-comparison">
                  <span className="metric-before">$22K</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">$85K</span>
                </div>
                <div className="improvement-badge">+289% Revenue Lift</div>
              </div>

              <div className="metric-card">
                <div className="case-details-metric-label">Bounce Rate</div>
                <div className="metric-comparison">
                  <span className="metric-before">64%</span>
                  <span className="metric-arrow">→</span>
                  <span className="metric-after">26%</span>
                </div>
                <div className="improvement-badge">59% Reduction</div>
              </div>
            </div>
          </div>
        </section>
      </div>
      {/* <CustomerReviews /> */}
    </>
  );
};

export default FirstCaseStory;
