import React from "react";
import "../styles/ComparisonTable.css";

const ComparisonTable = () => {
  const features = [
    "Unlimited Design Revisions",
    "Industry-Specific KPIs",
    "Thorough Competitor Analysis",
    "Timely Delivery of Research, Wireframes, & Mockups",
    "Data-Driven Optimization",
    "8+ Years of Marketing & Designing Experience",
    "Tech Agnostic",
    "No Contracts",
  ];

  return (
    <div className="ttcl-comparison-container">
      <div className="ttcl-comparison-wrapper">
        <h2 className="ttcl-comparison-title">
          TechTCL vs. Traditional Agency
        </h2>

        <div className="ttcl-comparison-table">
          <div className="ttcl-comparison-header">
            <div className="ttcl-comparison-header-cell"></div>
            <div className="ttcl-comparison-header-cell ttcl-comparison-header-ttcl">
              TechTCL
            </div>
            <div className="ttcl-comparison-header-cell ttcl-comparison-header-traditional">
              Traditional Agency
            </div>
          </div>

          {features.map((feature, index) => (
            <div key={index} className="ttcl-comparison-row">
              <div className="ttcl-comparison-feature">{feature}</div>
              <div className="ttcl-comparison-cell ttcl-comparison-cell-ttcl">
                <div className="ttcl-comparison-icon-check">
                  <svg viewBox="0 0 24 24">
                    <polyline points="20 6 9 17 4 12"></polyline>
                  </svg>
                </div>
              </div>
              <div className="ttcl-comparison-cell ttcl-comparison-cell-traditional">
                <div className="ttcl-comparison-icon-cross">
                  <svg viewBox="0 0 24 24">
                    <line x1="18" y1="6" x2="6" y2="18"></line>
                    <line x1="6" y1="6" x2="18" y2="18"></line>
                  </svg>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ComparisonTable;
