/* ════════════════════════════════
   MAIN BLOG PAGE — Hash-based routing
   ════════════════════════════════ */
export default function BlogSystem() {
  const [route, setRoute] = useState("list");
  const [blogSlug, setBlogSlug] = useState("");
  const [editSlug, setEditSlug] = useState("");

  useEffect(() => {
    const handleHash = () => {
      const hash = window.location.hash;
      if (hash === "#/admin") {
        setRoute("admin");
      } else if (hash.startsWith("#/blog/admin/edit/")) {
        setRoute("editor");
        setEditSlug(hash.replace("#/blog/admin/edit/", ""));
      } else if (hash.startsWith("#/blog/admin")) {
        setRoute("editor");
        setEditSlug("");
      } else if (hash.startsWith("#/blog/")) {
        setRoute("post");
        setBlogSlug(hash.replace("#/blog/", ""));
      } else {
        setRoute("list");
      }
    };
    handleHash();
    window.addEventListener("hashchange", handleHash);
    return () => window.removeEventListener("hashchange", handleHash);
  }, []);

  const goList = () => {
    window.location.hash = "";
    setRoute("list");
    window.scrollTo(0, 0);
  };
  const goPost = (slug) => {
    window.location.hash = "#/blog/" + slug;
    window.scrollTo(0, 0);
  };
  const goEditor = () => {
    window.location.hash = "#/blog/admin";
    setEditSlug("");
    window.scrollTo(0, 0);
  };
  const goAdmin = () => {
    window.location.hash = "#/admin";
    window.scrollTo(0, 0);
  };
  const goEditPost = (slug) => {
    window.location.hash = "#/blog/admin/edit/" + slug;
    window.scrollTo(0, 0);
  };

  if (route === "admin")
    return (
      <AdminDashboard
        onBack={goList}
        onBlogEditor={goEditor}
        onEditPost={goEditPost}
      />
    );
  if (route === "editor")
    return <BlogEditor onBack={goList} editSlug={editSlug} />;
  if (route === "post")
    return <BlogPost slug={blogSlug} onBack={goList} onBackToBlog={goList} />;
  return <BlogList onReadPost={goPost} onAdmin={goAdmin} />;
}
