import React, { useState } from "react";
import "../styles/CollapsibleTab.css";

const CollapsibleTab = () => {
  const [expandedSection, setExpandedSection] = useState(1);

  const sections = [
    {
      id: 1,
      title: "Audit & Analysis",
      content:
        "We start by comprehending your project requirements, goals, and expectations, including your target audience, marketing objectives, and specific design or branding preferences.",
    },
    {
      id: 2,
      title: "Competitive Research Advantage",
      content:
        "We analyze your competitors and market landscape to identify opportunities and best practices that will give your landing page a strategic advantage.",
    },
    {
      id: 3,
      title: "Gaining a Competitive Edge",
      content:
        "We leverage insights from our research to position your landing page uniquely in the market, ensuring it stands out and captures your target audience's attention.",
    },
    {
      id: 4,
      title: "Creating User-Focused Wireframes",
      content:
        "We design intuitive wireframes that prioritize user experience, mapping out the flow and structure to ensure seamless navigation and engagement.",
    },
    {
      id: 5,
      title: "Designing for Conversions",
      content:
        "We craft compelling designs with strategic placement of CTAs, persuasive copy, and visual elements that drive visitors to take action and convert.",
    },
  ];

  const toggleSection = (id) => {
    setExpandedSection(expandedSection === id ? null : id);
  };

  return (
    <div className="ttcl-collapsible-container">
      <div className="ttcl-collapsible-wrapper">
        <div className="ttcl-collapsible-header">
          <h1 className="ttcl-collapsible-title">
            Our Landing Page Design Services
          </h1>
          <h2 className="ttcl-collapsible-subtitle">Proven Framework</h2>
          <div className="ttcl-collapsible-description">
            <p className="ttcl-collapsible-description-intro">
              At Apexure, we adhere to a meticulous and structured process to
              deliver landing page design services tailored to your needs. Our
              approach includes:
            </p>
          </div>
        </div>

        <div className="ttcl-collapsible-sections">
          {sections.map((section) => (
            <div
              key={section.id}
              className={`ttcl-collapsible-section ${
                expandedSection === section.id
                  ? "ttcl-collapsible-expanded"
                  : ""
              }`}
            >
              <div
                className="ttcl-collapsible-section-header"
                onClick={() => toggleSection(section.id)}
              >
                <div className="ttcl-collapsible-section-number">
                  {section.id}
                </div>
                <h3 className="ttcl-collapsible-section-title">
                  {section.title}
                </h3>
                <div className="ttcl-collapsible-section-icon">
                  <svg viewBox="0 0 24 24">
                    <polyline points="6 9 12 15 18 9"></polyline>
                  </svg>
                </div>
              </div>
              <div className="ttcl-collapsible-section-content">
                <p className="ttcl-collapsible-section-text">
                  {section.content}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default CollapsibleTab;
