import React, { useState } from "react";
import { ArrowRight, TrendingDown } from "lucide-react";
import "../../styles/LandingPage.css";
import CustomerReviews from "../CustomerReviews";
import CollapsibleTab from "../CollapsibleTab";
import ComparisonTable from "../ComparisonTable";
import WhatHappensNext from "../WhatHappensNext";

const ShopifyServiceLanding = () => {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    message: "",
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Form submitted:", formData);
    alert("Thank you for your interest! We will contact you soon.");
    setFormData({ name: "", email: "", phone: "", message: "" });
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };


  // These values should be customized for each service
  const serviceData = {
    title: "Shopify Store Development",
    subtitle: "Build Your Dream E-commerce Store",
    description:
      "Transform your business vision into a stunning, high-performing Shopify store. Our expert developers create custom solutions tailored to your unique needs.",
    heroImage:
      "https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&h=600&fit=crop",
    benefits: [
      {
        heading: "Custom Theme Development",
        icon: TrendingDown,
      },
      {
        heading: "Mobile-Responsive Design",
        icon: TrendingDown,
      },
      {
        heading: "SEO Optimization",
        icon: TrendingDown,
      },
      {
        heading: "Payment Gateway Integration",
        icon: TrendingDown,
      },
      {
        heading: "Speed Optimization",
        icon: TrendingDown,
      },
      {
        heading: "App Integration & Customization",
        icon: TrendingDown,
      },
      {
        heading: "Speed Optimization",
        icon: TrendingDown,
      },
      {
        heading: "App Integration & Customization",
        icon: TrendingDown,
      },
    ],
    features: [
      {
        title: "Expert Development",
        description:
          "Elevate performance through expert landing page design services and conversion rate optimization strategies.",
        icon: "⚡",
      },
      {
        title: "Custom Solutions",
        description:
          "Elevate performance through expert landing page design services and conversion rate optimization strategies.",
        icon: "🎨",
      },
      {
        title: "Ongoing Support",
        description:
          "Elevate performance through expert landing page design services and conversion rate optimization strategies.",
        icon: "🛟",
      },
    ],
    process: [
      {
        step: "01",
        title: "Discovery & Planning",
        description:
          "We analyze your requirements and create a detailed project roadmap",
        icon: "🎯",
      },
      {
        step: "02",
        title: "Design & Development",
        description:
          "Our team builds your store with pixel-perfect design and clean code",
        icon: "⚡",
      },
      {
        step: "03",
        title: "Testing & Launch",
        description:
          "Rigorous testing followed by a smooth launch of your store",
        icon: "🚀",
      },
      {
        step: "04",
        title: "Support & Growth",
        description: "Ongoing support and optimization to scale your business",
        icon: "📈",
      },
    ],
    testimonials: [
      {
        name: "Sarah Johnson",
        company: "Fashion Boutique Co.",
        text: "TechTCL transformed our vision into reality. Our store looks amazing and sales have increased by 150%!",
        rating: 5,
      },
      {
        name: "Michael Chen",
        company: "Tech Gadgets Pro",
        text: "Professional, responsive, and incredibly talented. They delivered beyond our expectations.",
        rating: 5,
      },
      {
        name: "Emma Williams",
        company: "Organic Beauty Store",
        text: "The best decision we made was working with TechTCL. Our store is fast, beautiful, and easy to manage.",
        rating: 5,
      },
    ],
  };

  return (
    <div className="techtcl-landing-wrapper">
      {/* Hero Section */}
      <section className="techtcl-hero-section">
        <div className="techtcl-hero-container">
          <div className="techtcl-hero-content">
            <h1>{serviceData.title}</h1>
            <p>{serviceData.description}</p>
            <div className="techtcl-hero-buttons">
              <button
                className="techtcl-btn-primary"
                onClick={() =>
                  document
                    .getElementById("techtcl-contact")
                    .scrollIntoView({ behavior: "smooth" })
                }
              >
                Start Your Project <ArrowRight size={20} />
              </button>
              <button
                className="techtcl-btn-secondary"
                onClick={() =>
                  document
                    .getElementById("techtcl-features")
                    .scrollIntoView({ behavior: "smooth" })
                }
              >
                Learn More
              </button>
            </div>
          </div>
          <div className="techtcl-hero-image">
            <img src={serviceData.heroImage} alt={serviceData.title} />
          </div>
        </div>
      </section>


      

      {/* Benefits Section */}
      <section className="techtcl-section">
        <div className="techtcl-section-container">
          <div className="techtcl-section-header">
            <h2>What You Get</h2>
            <p>Comprehensive solutions designed to grow your business</p>
          </div>
          <div className="techtcl-benefits-grid">
            {serviceData.benefits.map((benefit, index) => (
              <div key={index} className="techtcl-benefit-card">
                <div className="techtcl-benefit-icon">
                  <benefit.icon size={24} />
                </div>
                <span
                  className="benefits-heading"
                  style={{ fontWeight: 600, color: "#1a1a1a" }}
                >
                  {benefit.heading}
                </span>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section
        id="techtcl-features"
        className="techtcl-section techtcl-section-gray"
      >
        <div className="techtcl-section-container">
          <div className="techtcl-section-header">
            <h2>Why Choose Us</h2>
            <p>We deliver excellence in every project</p>
          </div>
          <div className="techtcl-features-grid">
            {serviceData.features.map((feature, index) => (
              <div key={index} className="techtcl-feature-card">
                <div className="techtcl-feature-icon">{feature.icon}</div>
                <h3>{feature.title}</h3>
                <p>{feature.description}</p>
                <div className="shopify-hover-indicator"></div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Process Section */}
      <section className="techtcl-section">
        <div className="techtcl-section-container">
          <div className="techtcl-section-header">
            <h2>Our Process</h2>
            <p>A proven methodology for success</p>
          </div>
          <div className="techtcl-process-grid">
            {serviceData.process.map((item, index) => (
              <div key={index} className="techtcl-process-card">
                <div className="techtcl-process-step-wrapper">
                  <div className="techtcl-process-step">{item.step}</div>
                </div>
                <div className="techtcl-process-icon-wrapper">{item.icon}</div>
                <h3>{item.title}</h3>
                <p>{item.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Our Approach Section */}
      <CollapsibleTab />

      {/* whn section */}
      <WhatHappensNext />

      {/* Comparison Table Section */}
      <ComparisonTable />

      {/* Contact Form Section */}
      <section id="techtcl-contact" className="techtcl-contact-section">
        <div className="techtcl-contact-container">
          <div className="techtcl-section-header">
            <h2>Get in Touch</h2>
            <p>
              Fill out the form below and we'll get back to you within 24 hours
            </p>
          </div>
          <div className="techtcl-contact-form">
            <div className="techtcl-form-group">
              <label className="techtcl-form-label">Name *</label>
              <input
                type="text"
                name="name"
                className="techtcl-form-input"
                value={formData.name}
                onChange={handleChange}
                placeholder="John Doe"
              />
            </div>
            <div className="techtcl-form-group">
              <label className="techtcl-form-label">Email *</label>
              <input
                type="email"
                name="email"
                className="techtcl-form-input"
                value={formData.email}
                onChange={handleChange}
                placeholder="john@example.com"
              />
            </div>
            <div className="techtcl-form-group">
              <label className="techtcl-form-label">Phone</label>
              <input
                type="tel"
                name="phone"
                className="techtcl-form-input"
                value={formData.phone}
                onChange={handleChange}
                placeholder="+1 (555) 123-4567"
              />
            </div>
            <div className="techtcl-form-group">
              <label className="techtcl-form-label">Message *</label>
              <textarea
                name="message"
                className="techtcl-form-textarea"
                value={formData.message}
                onChange={handleChange}
                placeholder="Tell us about your project..."
              />
            </div>
            <button onClick={handleSubmit} className="techtcl-form-submit">
              Send Message
            </button>
          </div>
        </div>
      </section>

      {/* Testimonials Section */}
      <CustomerReviews />

      {/* CTA Section */}
      <section className="techtcl-cta-section">
        <div className="techtcl-section-container">
          <h2>Ready to Get Started?</h2>
          <p>Let's build something amazing together</p>
          <button
            className="techtcl-btn-primary"
            onClick={() =>
              document
                .getElementById("techtcl-contact")
                .scrollIntoView({ behavior: "smooth" })
            }
          >
            Contact Us Today <ArrowRight size={20} />
          </button>
        </div>
      </section>
    </div>
    
  );
};

export default ShopifyServiceLanding;
