import { useState, useEffect, useRef } from "react";
import "./ImpactSection.css";
import {
  Shirt,
  Sparkles,
  Dumbbell,
  Sofa,
  Pizza,
  PawPrint,
  Smartphone,
  Leaf,
} from "lucide-react";
const stats = [
  {
    number: "150",
    suffix: "+",
    label: "Projects Delivered",
    sub: "across all service types",
  },
  {
    number: "98",
    suffix: "%",
    label: "Client Satisfaction",
    sub: "measured across all projects",
  },
  { number: "12", suffix: "", label: "Core Services", sub: "under one roof" },
  {
    number: "5",
    suffix: "+",
    label: "Years of Expertise",
    sub: "in Shopify ecosystem",
  },
];

const services = [
  "Complete Shopify Store Setup",
  "Professional Dropshipping Website",
  "Seamless Sales Funnel Integration",
  "Shopify CRO & Speed Enhancement",
  "Figma-to-Shopify Conversion",
  "Shopify Brand Redesign & Refresh",
  "Effortless Website Migration",
  "Custom Website Development",
  "E-commerce Data Management",
  "E-commerce Data Visualization",
  "Advanced Data Analytics",
  "Shopify App Development",
];

const storeTypes = [
  { name: "General Store", pct: 88 },
  { name: "Niche Store", pct: 82 },
  { name: "One-Product", pct: 76 },
  { name: "Dropshipping", pct: 90 },
  { name: "Brand / DTC", pct: 70 },
  { name: "B2B Wholesale", pct: 54 },
];

const industries = [
  { icon: <Shirt size={20} color="#8B5CF6" />, name: "Fashion & Apparel" },
  { icon: <Sparkles size={20} color="#EC4899" />, name: "Beauty & Skincare" },
  { icon: <Dumbbell size={20} color="#F97316" />, name: "Fitness & Sports" },
  { icon: <Sofa size={20} color="#14B8A6" />, name: "Home & Living" },
  { icon: <Pizza size={20} color="#EF4444" />, name: "Food & Beverage" },
  { icon: <PawPrint size={20} color="#A78BFA" />, name: "Pet Supplies" },
  { icon: <Smartphone size={20} color="#3B82F6" />, name: "Tech & Gadgets" },
  { icon: <Leaf size={20} color="#22C55E" />, name: "Health & Wellness" },
];

function useCountUp(target, duration = 1800, start = false) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!start) return;
    let startTime = null;
    const num = parseInt(target);
    const step = (timestamp) => {
      if (!startTime) startTime = timestamp;
      const progress = Math.min((timestamp - startTime) / duration, 1);
      const ease = 1 - Math.pow(1 - progress, 3);
      setCount(Math.floor(ease * num));
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, [start, target, duration]);
  return count;
}

function StatCard({ number, suffix, label, sub, index, animate }) {
  const count = useCountUp(number, 1600, animate);
  return (
    <div className="impact-stat" style={{ "--i": index }}>
      <div className="impact-stat__number">
        <span className="impact-stat__count">{animate ? count : 0}</span>
        <span className="impact-stat__suffix">{suffix}</span>
      </div>
      <div className="impact-stat__label">{label}</div>
      <div className="impact-stat__sub">{sub}</div>
    </div>
  );
}

function BarRow({ name, pct, index, animate }) {
  return (
    <div className="store-row" style={{ "--i": index }}>
      <span className="store-row__name">{name}</span>
      <div className="store-row__track">
        <div
          className="store-row__fill"
          style={{
            "--pct": `${pct}%`,
            animationPlayState: animate ? "running" : "paused",
          }}
        />
      </div>
      <span className="store-row__pct">{animate ? `${pct}%` : "—"}</span>
    </div>
  );
}

export default function ImpactSection() {
  const [visible, setVisible] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) setVisible(true);
      },
      { threshold: 0.15 },
    );
    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);

  return (
    <section className="impact" ref={ref}>
      {/* Decorative rule + heading */}
      <div className={`impact__header ${visible ? "is-visible" : ""}`}>
        <div className="impact__eyebrow">
          <span className="impact__dot" />
          Our Track Record
        </div>
        <h2 className="impact__heading">
          Numbers That <br />
          <em>Tell the Story</em>
        </h2>
        <p className="impact__desc">
          Real outcomes from real projects — spanning store types, industries,
          and every Shopify challenge imaginable.
        </p>
      </div>

      {/* ── Stats strip ── */}
      <div className={`impact__stats ${visible ? "is-visible" : ""}`}>
        {stats.map((s, i) => (
          <StatCard key={s.label} {...s} index={i} animate={visible} />
        ))}
      </div>

      {/* ── Lower grid ── */}
      <div className={`impact__grid ${visible ? "is-visible" : ""}`}>
        {/* Services list — diagonal number layout */}
        <div className="impact__card impact__card--services">
          <div className="card__eyebrow">12 Specialties</div>
          <h3 className="card__title">
            Everything
            <br />
            Under One Roof
          </h3>
          <ol className="service-list">
            {services.map((s, i) => (
              <li key={s} className="service-list__item" style={{ "--i": i }}>
                <span className="service-list__num">
                  {String(i + 1).padStart(2, "0")}
                </span>
                <span className="service-list__name">{s}</span>
              </li>
            ))}
          </ol>
        </div>

        {/* Right column */}
        <div className="impact__col-right">
          {/* Store Types */}
          <div className="impact__card impact__card--stores">
            <div className="card__eyebrow">Store Types Built</div>
            <h3 className="card__title">
              Every Format,
              <br />
              Mastered
            </h3>
            <div className="store-bars">
              {storeTypes.map((s, i) => (
                <BarRow key={s.name} {...s} index={i} animate={visible} />
              ))}
            </div>
          </div>

          {/* Industries */}
          <div className="impact__card impact__card--industries">
            <div className="card__eyebrow">Industries Served</div>
            <h3 className="card__title">Across Every Niche</h3>
            <div className="industry-grid">
              {industries.map((item) => (
                <div className="industry-item" key={item.name}>
                  <span className="industry-item__icon">{item.icon}</span>
                  <span className="industry-item__name">{item.name}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
